  str_guide_pop_title_lineskill = "Combo en cadena",
  str_guide_pop_desc_lineskill = "Una vez que una cadena alcanza <color=#ff8f3d>una cierta longitud</color>, activará <color=#ff8f3d>automáticamente un Combo en Cadena</color>.\nGeneralmente, <color=#ff8f3d>cuanto más larga es la conexión</color>, <color=#ff8f3d>más poderoso es el</color> Combo en Cadena.\nCada combinación de cadena de Aurorian tiene diferentes efectos y condiciones de activación, ¡así que mezcla y combina como mejor te parezca!",
  str_guide_pop_extra_lineskill = "El verdadero valor de un Aurorian proviene de lo que muestra más allá de su poder.\n—Mensaje III de Reinhardt —",
  str_guide_pop_title_moreline = "Conexión multi-Aurorian",
  str_guide_pop_desc_moreline = "Cuando se despliegan varios Aurorians, solo actuarán aquellos con el mismo elemento que las fichas de la cadena.\n<color=#ff5f51>Las casillas rojas</color> activarán Aurorians de <color=#ff5f51>Fuego</color>, y <color=#6fd5ff>casillas azules</color> activarán Aurorians de <color=#6fd5ff>Agua</color>.\n<color=#85ff3b>Casillas verdes</color> activarán Aurorians de <color=#85ff3b>Bosque</color>, y <color=#fee039>Casillas amarillas</color> activarán Aurorians de <color=#fee039>Trueno</color>.\nNo se preocupe, el Capitán Aurorian <color=#ff8f3d>ignorará los elementos de las casillas </color> y actuará en cada ronda.",
  str_guide_pop_extra_moreline = "El mundo es bendecido por la Diosa, que llena el corazón de uno con luz.\n—Mensaje I de Reinhardt —",
  str_guide_pop_title_mainskill1 = "Habilidad activa",
  str_guide_pop_desc_mainskill1 = "Las habilidades activas se dividen en habilidades de ataque preventivo y habilidades de ataque no preventivo. ¡<color=#ff8f3d>Las habilidades de ataque preventivo</color> se pueden usar justo cuando comienza la batalla!\nLas habilidades activas deben <color=#ff8f3d>usarse antes de la conexión</color>, y <color=#ff8f3d>entrarán en un período de recuperación</color> después de su uso.\nLos diferentes Aurorians tienen diferentes Habilidades Activas, ¡y la combinación correcta de diferentes habilidades puede producir enormes beneficios!",
  str_guide_pop_extra_mainskill1 = "El tramo de tiempo ha germinado semillas de disputa en nuestros corazones, sin embargo, también ha creado magníficas maravillas.\n                                      —Mensaje II de Reinhardt—",
  str_guide_pop_title_mainskill2 = "Habilidad de conversión de casillas",
  str_guide_pop_desc_mainskill2 = "La habilidad de conversión de casillas <color=#ff8f3d>puede convertir ciertas casillas</color> y cambiar el <color=#ff8f3d>Tablero de Alquimia</color>.\nLa conversión de mosaicos brindará más <color=#ff8f3d>posibilidades para las cadenas</color> y es la habilidad de soporte más fuerte.\n¡Utilice la conversión de fichas en el momento adecuado para ejecutar su estrategia y lograr un cambio radical!",
  str_guide_pop_extra_mainskill2 = "Lo único que nunca cambia es el cambio en sí.\n—Mensaje IV de Reinhardt —",
  str_guide_pop_title_levelup = "Mejorar",
  str_guide_pop_desc_levelup = "Subir de Nivel y amasar el poder Aurorian",
  str_guide_pop_extra_levelup = "Descripción nivel XXX",
  str_guide_pop_title_lineskillrange = "Alcance del combo en cadena",
  str_guide_pop_desc_lineskillrange = "Confirmar el alcance de un Chain Combo es la forma más básica de aumentar la eficiencia del combate.\nEl rango de las diferentes habilidades de tus Aurorians varía. <color=#ff8f3d>No levante el dedo</color> después de conectarse, y podrá obtener una <color=#ff8f3d>vista previa</color> del rango de cada habilidad.\n<color=#ff8f3d>Ajustar el punto final de la cadena</color> cambiará el área que afecta la habilidad del Aurorian. ¡Esto es muy importante!",
  str_guide_pop_extra_lineskillrange = "El mayor honor entre los compañeros es confiar sus vidas los unos a los otros. —Mensaje VII de Reinhardt—",
  str_guide_pop_title_leaderskill = "Habilidad del capitán",
  str_guide_pop_desc_leaderskill = "Algunos Aurorians tienen una Habilidad Pasiva especial que supera a otros Aurorians, ¡esa es la Habilidad del Capitán!",
  str_guide_pop_extra_leaderskill = "La habilidad del Capitán es muy rara y puede aumentar significativamente las habilidades de los Aurorians con el mismo elemento.",
  str_guide_pop_title_jiguan = "Trampa",
  str_guide_pop_desc_jiguan = "Las trampas de llamas <color=#ff8f3d>rotarán con regularidad</color>, causando daño a los objetivos en <color=#ff8f3d>filas o columnas</color>.\nLas trampas pueden <color=#ff8f3d>atacarnos</color> o <color=#ff8f3d>a nuestros enemigos</color>, y pueden hacer maravillas si se usan con eficacia.\n¡Intenta mantenerte fuera de su rango de ataque y ten cuidado de que las trampas no bloqueen tu conexión!",
  str_guide_pop_extra_jiguan = "Había mucha basura en los viejos tiempos, pero muchas... ¡cosas interesantes también! ¿No es así?\n—Diario de Observación de Gronru—",
  str_guide_pop_title_muchaoguai = "Monstruo de cría",
  str_guide_pop_desc_muchaoguai = "Los monstruos de cría <color=#ff8f3d>no pueden moverse</color>, preol <color=#ff8f3d>invocarán continuamente eclipsites</color>. \nSi no los derrotas a tiempo, el campo de batalla estará plagado de enemigos.\n<color=#ff8f3d>Atacar directamente al monstruo en sí</color> es la mejor manera de lidiar con él, especialmente contra monstruos de tamaño mediano.\nY no digas que no te advertí: ¡<color=#ff8f3d>vencerlos con ataques de área es el camino a seguir</color>!",
  str_guide_pop_extra_muchaoguai = "Algunos Eclipsites son realmente asquerosos. Cuando se destrozan, hay algo pegajoso... (Datos borrados)\n                                      —Diario de Observación de Gronru—",
  str_guide_pop_title_shenyuan = "Casilla Abisal",
  str_guide_pop_desc_shenyuan = "Las Casillas Abisales no se pueden cruzar, pero los monstruos voladores sí pueden atravesarlas, al igual que tú, mediante teletransporte.",
  str_guide_pop_extra_shenyuan = "Puede pasar vía teletransportación.",
  str_guide_pop_title_moredamge = "Tipos de Cuerpo y Daño de los Eclipsites",
  str_guide_pop_desc_moredamge = "Las eclipsitas tienen una variedad de <color=#ff8f3d>tamaños</color>, y las más comunes son las eclipsitas de una sola baldosa.\nHay eclipsitas Quadriune e incluso eclipsitas más grandes que existen, aunque son enormes y fuertes, son más vulnerables al daño en la batalla.\n<color=#ff8f3d>¡Dado que ocupan varias casillas, recibirán daño varias veces de ataques de área, </color>así como de ataques en cadena!",
  str_guide_pop_extra_moredamge = "Cuanto más grande sea el enemigo, más fácil es tratar con él. Sólo cierra los ojos y golpéalos.\n                                      —Citas de Barton (inéditas)—",
  str_guide_pop_title_leveltask = "Misión de Etapa",
  str_guide_pop_desc_leveltask = "Hay muchos tipos de Misiones de Etapa, y puedes superar la etapa completándolas",
  str_guide_pop_extra_leveltask = "Despeja la etapa comp. las misiones de etapa",
  str_guide_pop_title_escape = "Punto de Escape",
  str_guide_pop_desc_escape = "El punto de escape es una función a través de la cual puedes completar una etapa especial. Al <color=#ff8f3d>pasar a una casilla específica</color>, puede reclamar la victoria instantáneamente.\nTenga en cuenta que el punto de escape está <color=#ff8f3d>bloqueado</color> inicialmente y solo se puede desbloquear si se cumplen determinadas condiciones.\nHay muchas condiciones de desbloqueo, como <color=#ff8f3d>recolectar elementos o derrotar a Eclipsites</color>.",
  str_guide_pop_extra_escape = "No hay vergüenza al huir. Estos retiros temporales son por el bien de las mayores ambiciones...\n                                      —Cartas de Sharona—",
  str_guide_pop_title_monsterinfo = "Ver detalles",
  str_guide_pop_desc_monsterinfo = "<color=#ff8f3d>Toque y mantenga presionada la casilla debajo de los pies del monstruo</color> para ver su rango de ataque y otros detalles.\n¡Vigilar los rasgos del oponente te hará invencible!",
  str_guide_pop_extra_monsterinfo = "Si te conoces a ti mismo y conoces a tus enemigos, nunca serás derrotado.\n—Tomo antiguo desconocido, extracto incompleto—",
  str_guide_pop_title_jiguangshike = "Hora de Aurora",
  str_guide_pop_desc_jiguangshike = "Una vez que una cadena <color=#ff8f3d>alcanza las 15 casillas</color>, se activará Hora de Aurora y obtendrás una oportunidad adicional de actuar.\nDurante el tiempo de Aurora, los Aurorians pueden usar sus habilidades activas preparadas y también pueden activar sus combos en cadena a través de otra cadena.\nHora de Aurora <color=#ff8f3d>solo se puede activar una vez por ronda</color>, lo que te brinda grandes beneficios en la batalla.",
  str_guide_pop_extra_jiguangshike = "Solo conocemos trozos y piezas sobre el poder mágico de la luz.\n—Tomo antiguo desconocido, extracto incompleto—",
  str_guide_pop_title_jianglihuihe = "Tiempo extra",
  str_guide_pop_desc_jianglihuihe = "En White Night, Black Underbelly en un cierto nivel de dificultad, despeja el escenario en momentos específicos para ingresar a Bonus Time.\n¡Habrá múltiples Eclipsites Corruptos en el campo de batalla, y derrotarlos te dará Nightium extra!\nTenga en cuenta que su <color=#ff8f3d>la movilidad es muy alta</color>, permitiéndoles evadir nuestros ataques.",
