  str_guide_warn_50010 = "¡Completa misiones de aventura y obtén muchas recompensas!",
  str_guide_warn_50011 = "¡Obtén cientos de premios en el juego, incluidos grandes premios especiales!",
  str_guide_warn_50012 = "Recoge pétalos de flor de nube para desbloquear más de la historia y otras recompensas.",
  str_guide_warn_50013 = "Usa Prisma en la Historia Principal y la Incursión de Recursos para obtener Pétalos de Flor de Nube.",
  str_guide_warn_50014 = "Si tienes preguntas, asegúrate de consultar las reglas precisas del evento.",
  str_guide_warn_50015 = "¡Comienza una nueva aventura!",
  str_guide_warn_50016 = "Durante el periodo del evento, habrá nuevas etapas disponibles—¡complétalas para obtener Cupones Prinny!",
  str_guide_warn_50017 = "Las etapas difíciles consumirán Puntos de Acción. Los Puntos de Acción se recuperan automáticamente con el tiempo, ¡recuerda utilizarlos antes de llegar al tope!",
  str_guide_warn_50018 = "También puedes conseguir Cupones Prinny en las etapas de Historia Principal y en etapas de Incursión de Recursos que consumen Prisma.",
  str_guide_warn_50019 = "Después que comience la Ola de Calor, ¡podrás desbloquear más de la historia y etapas desafiantes!",
  str_guide_warn_50020 = "Cuando empiece Congelación Cerebral, podrás ayudarme con mis ingeniosos planes de verano...",
  str_guide_warn_50021 = "Recibirás recompensas por iniciar sesión durante el periodo del evento, ¡así que recuerda conectarte todos los días!",
  str_guide_warn_50022 = "Esta es la tienda de Cupones Prinny, ¡donde puedes canjear tus Cupones Prinny por increíbles recompensas!",
  str_guide_warn_50023 = "Participar en el evento te permitirá completar las misiones de tu Libro de Eventos Especiales, ganando varias recompensas.",
  str_guide_warn_50024 = "Si tienes preguntas, ¡consulta las reglas específicas aquí!",
  str_guide_warn_50025 = "Puedes subir el nivel de tu Libro de Eventos Especiales completando las misiones que contiene y ganando puntos de Contribución.",
  str_guide_warn_50026 = "Cada vez que mejores tu Libro de Eventos Especiales, ¡recibirás la recompensa de nivel correspondiente!",
  str_guide_warn_50027 = "¡Puede ver todas tus recompensas del Libro de Eventos Especiales aquí!",
  str_guide_warn_50028 = "Toca aquí para ver tus misiones del Libro de Eventos Especiales.",
  str_guide_warn_50029 = "Las misiones del Libro de Eventos Especiales incluyen misiones permanentes y misiones de eventos.",
  str_guide_warn_50030 = "Las misiones de eventos estarán disponibles sólo en momentos específicos. Por favor, ¡asegúrate de completarlas a tiempo!",
  str_guide_warn_50031 = "Los clientes están empezando a formar una fila... ¡Deberíamos empezar a hacer más granizados lo antes posible!",
  str_guide_warn_50032 = "Cada cliente pedirá un tipo de granizado diferente. ¡Elige los ingredientes adecuados para prepararlos!",
  str_guide_warn_50033 = "El estado de ánimo de los clientes empezará a empeorar mientras esperan. Entre mejor sea su estado de ánimo, ¡más alta será tu calificación!",
  str_guide_warn_50034 = "Para hacer granizados, deberás elegir primero el tamaño correcto de la porción.",
  str_guide_warn_50035 = "Luego puedes elegir el sirope.",
  str_guide_warn_50036 = "¡Selecciona los ingredientes adecuados!¡El orden en que selecciones los ingredientes y el sirope no importa aquí!",
  str_guide_warn_50037 = "Toca al cliente para enviar su granizado, ¡y el pedido está completo!",
  str_guide_warn_50038 = "Completar cierto número de pedidos seguidos activará la Congelación Cerebral, ¡ayudándote a completar los siguientes pedidos en cuestión de segundos!",
  str_guide_warn_50039 = "¡También recibirás recom. adic. tras completar pedidos consecutivos!",
  str_guide_warn_50040 = "No te preocupes si te equivocas al preparar un granizado—¡sólo toca aquí para desecharlo!",
  str_guide_warn_50041 = "Toca aquí para detener la producc. de granizados y toma un descanso.",
  str_guide_warn_50042 = "¡Y eso es todo lo que necesitas saber sobre cómo hacer granizados! Ahora, ¡volvamos al!",
  str_guide_warn_50043 = "¡El evento Endgame ya ha comenzado! ¡Entra aquí y prepárate para emocionantes retos!",
  str_guide_warn_50044 = "¡Completa los desafíos para ganar puntos y cámbialos aquí por increíbles recompensas!",
  str_guide_warn_50045 = "La historia de esta aventura se puede encontrar en el Mito del Juego Final.",
  str_guide_warn_50046 = "Si quieres estar al día con la historia hasta ahora, puedes revisarla aquí.",
  str_guide_warn_50047 = "¡Acepta los retos del evento y completa las misiones en tu Libro de Eventos Especiales!",
  str_guide_warn_50048 = "¡Inicia sesión a diario para reclamar recompensas exclusivas! ¡Recuerda conectarte al juego todos los días!",
  str_guide_warn_50049 = "Esta etapa cuenta con mecanismos únicos.¡Tendrás que seleccionar un nivel de dificultad adecuado antes de realizar el reto!",
  str_guide_warn_50050 = "Primero, selecciona el nivel de dificultad de la etapa. Cada nivel de dificultad otorga una cantidad de puntos base correspondiente.",
  str_guide_warn_50051 = "Luego, selecciona los efectos adicionales de la etapa. Cada efecto da un multiplicador de puntos correspondiente.",
  str_guide_warn_50052 = "¡Multiplica tus puntos base por tu multiplicador total para obtener tu puntuación final!",
  str_guide_warn_50053 = "Después de seleccionar tu dificultad, ¡puedes empezar la batalla!",
  str_guide_warn_50054 = "¡Entra en acción con Ataque Fuego de las Dunas! ¡Tu nueva aventura comienza ahora!",
  str_guide_warn_50055 = "Desafía el modo Vanguardia Final todos los días y gana mérito al acabar con un sinfín de enemigos.",
  str_guide_warn_50056 = "¡Cuantos más Méritos ganes, más alto estarás en la Clasificación Fuego de las Dunas y más recompensas de Mérito obtendrás!",
  str_guide_warn_50057 = "Participa en el evento Ataque Fuego de las Dunas para completar misiones en tu Libro de Eventos Especiales.",
  str_guide_warn_50058 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_50059 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_50060 = "¡El evento Carta de los Cielos ha comenzado! ¿Estás listo para una nueva aventura?",
