  str_guide_warn_50062 = "Los Bocadillos de Unión se pueden utilizar para restaurar el Puesto Eraveil.¡Vamos al puesto!",
  str_guide_warn_50063 = "Supera las etapas de la historia del evento y reconstruye el puesto, completarás las misiones correspondientes en tu Libro de Eventos Especiales.",
  str_guide_warn_50064 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_50065 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
