  str_guide_warn_509005 = "¡Sí, aquí tenemos muchos artículos, incluidas semillas de árboles, Chubb!",
  str_guide_warn_509006 = "¡Tenemos que discutir cómo gastar el dinero! Toque aquí para volver.",
  str_guide_warn_510002 = "Tenemos tres formas de criar Chubbs. Mejoramiento por mutación, mejoramiento dirigido y mejoramiento por transformación. ¡Intentemos primero la reproducción por mutación!",
  str_guide_warn_510003 = "Agregue una semilla de árbol único aquí como la semilla del sujeto, Chubb.",
  str_guide_warn_510004 = "Agregue aquí otra semilla de la misma calidad que Mutation Factor, Chubb.",
  str_guide_warn_510005 = "Toque aquí para comenzar a criar. ¡Un árbol único crecerá después de un tiempo, Chubb!",
  str_guide_warn_510006 = "Si no puedes esperar, usa un Diluyente para acelerar las cosas, Chubb.",
  str_guide_warn_510007 = "Si tienes alguna pregunta, ¡toca aquí para obtener ayuda, Chubb!",
  str_guide_warn_511001 = "La tierra de la fertilidad se puede encontrar en la pestaña Mobiliario especial. Pulse aquí. ¡Cachero!",
  str_guide_warn_511002 = "Luego, toca la pestaña Land of Fertility. ¡Cachero!",
  str_guide_warn_511003 = "Esta es la Tierra de la Fertilidad. ¡Cachero! Con esta tierra, puedes criar árboles únicos. ¡Cachero!",
  str_guide_warn_512001 = "Toca aquí para decorar.",
  str_guide_warn_512002 = "La tierra de la fertilidad se puede encontrar en la pestaña Mobiliario especial. ¡Pulse aquí!",
  str_guide_warn_512003 = "Luego, ¡toca la pestaña Tierra de fertilidad!",
  str_guide_warn_512004 = "Esta es la Tierra de la Fertilidad. ¡Toca aquí para colocarlo!",
  str_guide_warn_5110001 = "Navegador, el Aurorian ha alcanzado el nivel máximo. Para seguir subiendo de nivel, debes realizar la Ascensión para superar el límite actual.",
  str_guide_warn_5110004 = "¡Toca para ver los materiales necesarios para la Ascensión!",
  str_guide_warn_5110005 = "En caso de materiales insuficientes, hay varias formas de adquirirlos, incluyendo recolectarlos de las etapas correspondientes o subir de nivel el Taller para fabricarlos.",
  str_guide_warn_19050101 = "¡Ha comenzado \"Árboles, peces y una vida lenta\"! ¿Estás listo para una nueva aventura?",
  str_guide_warn_19050102 = "En Teatime Pleasantries nos enfrentaremos a una serie de difíciles desafíos.",
  str_guide_warn_19050103 = "¡Sigue rastreando señales y buscando tesoros con Chubb en Investigación detallada II!",
  str_guide_warn_19050104 = "Completar etapas del evento y gastar Prism otorga boletos de la Asociación Andersen que se pueden usar para canjear varias recompensas de la Asociación Andersen.",
  str_guide_warn_19050105 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
