  str_guide_warn_19050107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11000101 = "el viaje en Dawn ¡el evento ha comenzado! ¿Estás listo para una nueva aventura?",
  str_guide_warn_11000102 = "Nuestros nuevos amigos de Pangalo parecen preocupados por algo... ¡Ayúdalos en Visitantes de Cloud Gardens!",
  str_guide_warn_11000103 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11000201 = "¡Heist Under a Moonlit Night ya está disponible! ¡Sube a bordo para vivir aventuras con los Phantom Thieves!",
  str_guide_warn_11000202 = "Usa el prisma en las etapas de la historia principal y la incursión de recursos para obtener puntos de infiltración.",
  str_guide_warn_11000203 = "¡Infíltrate en la mazmorra desde aquí, consume puntos de infiltración para derrotar a los enemigos y recibe una amplia gama de recompensas!",
  str_guide_warn_11000204 = "Esta es la etapa de prueba para Phantom Thieves. Complétalo para obtener recompensas.",
  str_guide_warn_11000205 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11000206 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_11000207 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11050101 = "¡El evento Summer's Breeze & The Port of Hope ha comenzado! ¿Estás listo para una nueva aventura?",
  str_guide_warn_11050102 = "En Strange Alleyway Shadows nos enfrentaremos a una serie de difíciles desafíos.",
  str_guide_warn_11050103 = "¡En Heart-Throbbing Divination, conviértete en un detective e investiga el caso de un objeto perdido con tres bellas damas!",
  str_guide_warn_11050104 = "Las monedas de Harbor Fair obtenidas al completar las etapas del evento y gastar Prism se pueden usar para canjear varias recompensas de Street Fair.",
  str_guide_warn_11050105 = "¡Mientras te aventuras, pon a prueba tus habilidades culinarias en Food Cart King para ganar varias recompensas!",
  str_guide_warn_11050106 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11050107 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_11050108 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11050201 = "Los clientes empiezan a hacer cola... ¡Deberíamos empezar a hacer más udon lo antes posible!",
  str_guide_warn_11050202 = "Cada cliente pedirá un tipo diferente de udon. ¡Elige los ingredientes adecuados para prepararlo para ellos!",
  str_guide_warn_11050203 = "El estado de ánimo de los clientes empezará a empeorar mientras esperan. Entre mejor sea su estado de ánimo, ¡más alta será tu calificación!",
  str_guide_warn_11050204 = "Al hacer udon, primero deberá elegir el tamaño de porción correcto.",
  str_guide_warn_11050205 = "Entonces puedes elegir la sopa.",
  str_guide_warn_11050206 = "¡Seleccione los ingredientes correctos! ¡Aquí no importa el orden en que seleccionas los ingredientes y la sopa!",
  str_guide_warn_11050207 = "Toque al cliente para enviar su udon y el pedido estará completo.",
  str_guide_warn_11050208 = "Completar una cierta cantidad de pedidos seguidos activará Topping Frenzy, ¡lo que te ayudará a completar los siguientes pedidos en cuestión de segundos!",
  str_guide_warn_11050209 = "¡También recibirás recom. adic. tras completar pedidos consecutivos!",
  str_guide_warn_11050210 = "No se preocupe si comete un error mientras prepara los udon, ¡simplemente toque aquí para tirarlos!",
  str_guide_warn_11050211 = "Toque aquí para dejar de cocinar fideos y tomar un descanso.",
  str_guide_warn_11050212 = "¡Y eso es todo lo que necesitas saber para hacer udon! ¡Ahora, volvamos al trabajo!",
  str_guide_warn_11100101 = "¡El evento Summer's Breeze & The Port of Hope ha comenzado! ¿Estás listo para una nueva aventura?",
  str_guide_warn_11100102 = "Las tarjetas Morphing obtenidas al completar las etapas de la historia principal o la incursión de recursos que requieren Prism se pueden usar para canjear varias recompensas de Enchanted Valet Stand.",
  str_guide_warn_11100103 = "A todos en Cloud Gardens les apasiona construir una piscina. ¡Puedes ver las nuevas hazañas de Cloud Gardens en Let's Go Swimming!",
  str_guide_warn_11100104 = "¡Sigue rastreando señales y buscando tesoros con Chubb en Investigación detallada III!",
  str_guide_warn_11100105 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11100106 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_11100107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11200101 = "¡El evento Adiós, Mi \"País de las Maravillas\" ha comenzado! Una nueva aventura comienza aquí y ahora.",
  str_guide_warn_11200102 = "En No Man's Land, nos enfrentaremos a una serie de difíciles desafíos.",
  str_guide_warn_11200103 = "Los casquillos vacíos que se obtienen al completar etapas del evento y gastar prisma se pueden usar para canjear varias recompensas del depósito de suministros.",
  str_guide_warn_11200104 = "En Street Errands, exploraremos más a fondo la ciudad y recopilaremos información y noticias en las calles.",
  str_guide_warn_11200105 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11200106 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_11200107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11200203 = "Esta es una búsqueda peligrosa y gratificante. ¡Vámonos ahora!",
  str_guide_warn_11200204 = "El ascensor central puede llevarnos directamente a las profundidades, pero está lleno de gases nocivos debajo, por lo que no se puede explorar por ahora.",
  str_guide_warn_11200205 = "Aquí hay una lista de recompensas de Illumina. Cuanto más nos aventuremos, más recompensas obtendremos.",
  str_guide_warn_11200206 = "De todos modos, ¡veamos si podemos encontrar una manera de eliminar los gases nocivos!",
  str_guide_warn_11200207 = "Los Eclipsites se han apoderado de todos los Ventiladores aquí. Activa todos los ventiladores para eliminar los gases nocivos y continúa explorando el siguiente piso.",
  str_guide_warn_11200208 = "Necesitarás colocar 5 Aurorianos en cada Ventilador para activarlo. Los Ventiladores no se activarán si retira los Aurorianos antes de que se complete la purificación en el suelo.",
  str_guide_warn_11200209 = "Activa todos los Ventiladores colocando varios equipos de diferentes Aurorianos para continuar explorando.",
  str_guide_warn_11200210 = "Illumina ha proporcionado información de exploración más detallada. Toca aquí para verlo.",
  str_guide_warn_11300101 = "¡El único corte de los gritos! ¡el evento ha comenzado! Una nueva aventura comienza aquí y ahora.",
  str_guide_warn_11300102 = "Las Monedas antiguas obtenidas al completar las etapas del evento y gastar Prisma se pueden usar para canjear varias recompensas de The Secret Room.",
  str_guide_warn_11300103 = "¡A todos en Cloud Gardens les apasiona construir un set de filmación en Cloud Gardens! Puedes ver la nueva hazaña de Cloud Gardens: ¡Establecer tiempo de construcción!",
  str_guide_warn_11300104 = "¡Podemos comenzar a filmar una vez que se complete el set! ¡También obtendrás increíbles recompensas de los Chubbs después de filmar películas!",
  str_guide_warn_11300105 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11300106 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_11300107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11400102 = "¡Usa el prisma para superar las etapas de la historia principal y la incursión de recursos para obtener piezas de desecho y dárselas a Axelia para que las reúna! ¡Serás recompensado generosamente!",
  str_guide_warn_11400103 = "Todos en Cloud Gardens parecen estar entusiasmados con la celebración de una competencia de pesca. Echa un vistazo al nuevo evento Cloud Gardens Feats: ¡Una captura extraordinaria!",
  str_guide_warn_11400104 = "¡Completa desafíos con tus nuevos amigos para obtener recompensas de Lumamber!",
  str_guide_warn_11400105 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11400106 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_11400107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11500101 = "¡El evento Starry Adventure: Heaven-Shaking Melody ha comenzado! ¡Vamos a realizar un concierto único junto con Goldie!",
  str_guide_warn_11500102 = "En Dreamy Nostalgia nos enfrentaremos a una serie de difíciles desafíos.",
  str_guide_warn_11500103 = "Goldie Merch obtenido al completar etapas del evento y gastar Prism se puede usar para canjear varias recompensas de Brandy's Tabloids.",
  str_guide_warn_11500104 = "Una misteriosa guarida de Eclipsite ha aparecido cerca del Territorio Secreto. ¡Los Navegantes pueden superar el obstáculo aprendiendo Habilidades de Dominio de Talento y usando reliquias para ganar Lumamber!",
  str_guide_warn_11500105 = "En Starlit Agency, Navigator se convertirá en el agente de Goldie. ¡Bríndele capacitación y organice actividades para finalmente enviarla al escenario del concierto!",
  str_guide_warn_11500106 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11500107 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_11500108 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11500201 = "Comencemos, Navegante. Esta es la Agencia Starlit, donde entrenaremos a los ídolos y organizaremos eventos para eventualmente subirlos al escenario.",
  str_guide_warn_11500202 = "La agencia nos ha fijado unos objetivos. Las recompensas están disponibles después de la finalización. Los recuerdos del entrenamiento también se registrarán aquí.",
  str_guide_warn_11500203 = "Si no está satisfecho con el entrenamiento, puede volver a seleccionar momentos clave para tomar una decisión diferente.",
  str_guide_warn_11500204 = "¡Hora de empezar a entrenar, Navegante!",
  str_guide_warn_11500301 = "Esta es la cuenta regresiva hasta el concierto. ¡faltan 13 días! Tienes tu trabajo hecho por ti.",
  str_guide_warn_11500302 = "Pero debemos ganar 150.000 fans antes de que podamos realizar un concierto.",
  str_guide_warn_11500303 = "Ser un ídolo significa mucho entrenamiento. Hay tres modos de entrenamiento disponibles. ¡Asegúrate de mantener la calma cuando aparezcan los paparazzi!",
  str_guide_warn_11500304 = "Aquí están mis habilidades de ídolo. Los modos de entrenamiento los mejorarán.",
  str_guide_warn_11500305 = "¡Organizar eventos puede ayudarnos a ganar más fanáticos para que podamos alcanzar el requisito para el concierto!",
  str_guide_warn_11500306 = "Aquí está la lista de tareas pendientes de esta semana, puede usarla como referencia para la programación. Habla con la gente durante la capacitación y es posible que obtengas algo de ella.",
  str_guide_warn_11500307 = "El resto de la información se encuentra en el Manual del Productor. ¡Consúltalo siempre que necesites algo!",
  str_guide_warn_11500402 = "Ve a la Guarida para comenzar el desafío. Además de Lumamber, los jugadores también obtendrán Talent Mastery EXP para aumentar sus niveles de talento y ganar puntos de dominio de talento para volverse más poderosos.",
  str_guide_warn_11500403 = "Aquí es donde puedes encontrar misiones de Recompensa de guarida. Completar misiones también te hará ganar Puntos de Dominio de Talento.",
  str_guide_warn_11500404 = "¡Gasta puntos de dominio de talento para desbloquear habilidades de dominio de talento, equipo especial de Caelestite y reliquias para hacer que los desafíos de guarida sean más fáciles!",
  str_guide_warn_11500405 = "Todos los días, diferentes Aurorianos de prueba estarán disponibles para usar en Lair Challenges.",
  str_guide_warn_11500406 = "Puedes encontrar más información sobre la guarida aquí. Siéntase libre de navegar en cualquier momento.",
  str_guide_warn_11500601 = "Gana suficiente EXP de Dominio de Talento para aumentar tu Nivel de Talento y ganar Puntos de Dominio de Talento.",
  str_guide_warn_11500602 = "Gasta puntos de dominio de talento para activar dominios de talento como equipo especial de Caelestite para impulsar a tu equipo.",
  str_guide_warn_11500603 = "Después de gastar suficientes Puntos de Dominio de Talento, pueden aparecer Reliquias poderosas al azar durante los Desafíos de Guarida.",
  str_guide_warn_11500604 = "Puedes equipar equipo especial de Caelestite aquí. Proporcionan habilidades poderosas adicionales durante el desafío.",
  str_guide_warn_11500605 = "Si desea editar sus Dominios de talentos, puede restablecer los Dominios de talentos activados y los Puntos de dominio de talentos gastados sin costo alguno.",
  str_guide_warn_11500701 = "Toca aquí para ver los Aurorianos de tu equipo.",
  str_guide_warn_11600101 = "¡El evento Etched Upon the Ocean ha comenzado! ¡Únete a un elenco de nuevos amigos de Longzhou mientras buscamos un tesoro perdido y descubrimos secretos misteriosos en The Homecoming!",
  str_guide_warn_11600102 = "En Lost Ship At Sea nos enfrentaremos a una serie de difíciles desafíos.",
  str_guide_warn_11600103 = "Los pagarés de Lin Guild obtenidos al completar etapas del evento y gastar Prism se pueden usar para canjear varias recompensas de The Docks.",
  str_guide_warn_11600104 = "Durante el Festival de Primavera, la gente de Longzhou prepara un suntuoso festín llamado Cena de la Unidad. ¡Ayuda a Dantang a encontrar recetas para preparar deliciosos platos y obtener varias recompensas, incluida Lumamber!",
  str_guide_warn_11600105 = "Un libro de visitas anónimo ha aparecido en el set. Poco a poco se irá llenando de comentarios anónimos. ¡Lea estos mensajes para obtener nuevos guiones de películas!",
  str_guide_warn_11600106 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11600107 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_11600108 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11700101 = "¡El evento Voto Fragmentario ha comenzado! Embárcate en una aventura con tus nuevos amigos de la Unión de Mensajeros en la Peregrinación de la Corona de la Luna.",
  str_guide_warn_11700102 = "En Feather Seal Crisis, nos enfrentaremos a una serie de difíciles desafíos.",
  str_guide_warn_11700103 = "Las plumas raras obtenidas al completar las etapas del evento y gastar el prisma se pueden canjear por varias recompensas en el Courier Express.",
  str_guide_warn_11700104 = "¡En Sweet Delivery, puede experimentar la vida trabajando en una publicación de Courier Union y resolver la interminable crisis de los mejores deseos del Navigator al mismo tiempo!",
  str_guide_warn_11700105 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11700106 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_11700107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11700201 = "Esta es la información de su pedido recibido actualmente. Toca un avatar para cambiar de orden.",
  str_guide_warn_11700202 = "Primero terminemos el pedido de Lilica. Necesita ropa, pan y vino.",
  str_guide_warn_11700203 = "A la derecha, puede encontrar la lista completa de productos.",
  str_guide_warn_11700204 = "¡Pongamos un poco de pan en el paquete!",
  str_guide_warn_11700205 = "Mientras toca y mantiene presionado para arrastrar los productos, también puede tocar los botones para rotar (tecla R) y voltear (tecla T).",
  str_guide_warn_117002051 = "Mientras toca y mantiene presionado para arrastrar los productos, también puede tocar los botones para rotar y voltear.",
  str_guide_warn_11700206 = "Después de que todos los artículos del pedido se hayan colocado en el paquete, recuerde tocar el botón de embalaje para enviarlo. Si no se han colocado todos los artículos en el paquete, el progreso de finalización del pedido final se verá afectado.",
  str_guide_warn_11700207 = "Toque aquí para pausar el empaquetado.",
  str_guide_warn_11700208 = "Ahora que sabe todo sobre el proceso de flujo de trabajo, ¡continuemos empacando!",
  str_guide_warn_11800101 = "¡El evento Confess Before the Gavel Strikes ha comenzado! Embárcate en una aventura con todos en el Hall of Justice durante Heartfelt Admissions.",
  str_guide_warn_11800102 = "En When the Flowers Wither, nos enfrentaremos a una serie de difíciles desafíos.",
  str_guide_warn_11800103 = "Los fragmentos de yeso obtenidos al completar etapas del evento y gastar prisma se pueden usar para canjear varias recompensas de la colección de pruebas.",
  str_guide_warn_11800104 = "Durante el evento Love on Trial, actuarás como juez asistente, escuchando los casos en cuestión e investigando la verdad con los miembros de la División de Romance.",
  str_guide_warn_11800105 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11800106 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_11800107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11800201 = "No todo el mundo llega a trabajar en el Salón de la Justicia. ¡Definitivamente aprovecharía al máximo esta oportunidad si fuera tú! Toque aquí para ir al Salón de la Justicia y ver qué casos le esperan.",
  str_guide_warn_11800202 = "Los casos pueden tener diferentes finales dependiendo de cómo transcurra el juicio. Si se queda atascado mientras investiga, puede ir a Registro de caso y elegir un punto de selección de historia correspondiente para tomar decisiones diferentes.",
  str_guide_warn_11800203 = "Definitivamente serás recompensado por tu arduo trabajo. ¡Completa historias para desbloquear finales y cumple varias condiciones para reclamar insignias y recompensas aquí!",
  str_guide_warn_11800204 = "He escrito todos los detalles aquí. Recuerde leerlos nuevamente si hay algo que aún no entiende.",
  str_guide_warn_11800301 = "¡Guau! ¿Ya aprendiste a recolectar evidencia tan rápido? Toda esta evidencia entrará en uso cuando sea el momento de presentar la evidencia.",
  str_guide_warn_11800401 = "Así es. ¡Es hora de presentar las pruebas! Las pruebas que ha recopilado aparecerán en la lista de pruebas. No olvide tocarlos para ver información más detallada.",
  str_guide_warn_11800402 = "¡La presentación de pruebas incorrectas puede afectar su competencia y el resultado del juicio!\nTratemos de seleccionar la prueba correcta de acuerdo con la pregunta de Ángel. ¡Toca aquí para contraatacar!",
  str_guide_warn_11800501 = "El Cuaderno del juez es un símbolo de la identidad de un juez. ¿Tienes curiosidad por su contenido?",
  str_guide_warn_11800502 = "¡Oh! Las pruebas y los detalles que recopila se registran aquí. Eso hace que sea realmente conveniente verificar todo.",
  str_guide_warn_11800503 = "También es muy importante fomentar una relación más sólida con sus colegas, ya que la relación entre usted y sus colegas también puede afectar la dirección de la prueba. ¡Buena suerte!",
  str_guide_warn_11800601 = "¡Permítanme presentarles las reglas básicas del juego! Necesitas controlar a tu personaje, luchando a través de todas las etapas hasta llegar al jefe final: ¡Gronkenstein Ruu!",
  str_guide_warn_11800602 = "Puedes tocar este botón para cambiar de personaje, pero todos son exactamente iguales en términos de juego real, ¡no lo juzgues!",
  str_guide_warn_11800603 = "Si hay algo que todavía no entiendes, puedes consultar la documentación aquí.",
  str_guide_warn_11800701 = "Las etapas se desbloquearán gradualmente con el tiempo. ¡Probemos la primera etapa!",
  str_guide_warn_11800702 = "¡Mientras completes el primer objetivo de cada etapa, lo superarás! ¡También puedes ir por todos los objetivos si quieres!",
  str_guide_warn_11800703 = "¡Preparémonos para la fiesta!",
  str_guide_warn_11800801 = "¡Eso es todo! ¡Tienes que mantener a tu personaje avanzando y tratar de no dejar que los Eclipsites te atrapen! ¡Llega al objetivo!",
  str_guide_warn_11800802 = "¡Hay un eclipse normal más adelante! ¡Aprovecha el momento perfecto para saltar sobre su cabeza, entonces se acabará el juego para ese normie novato!",
  str_guide_warn_11800803 = "¡Ahora! ¡Toca el botón Saltar!",
  str_guide_warn_118008031 = "¡Ahora! ¡Toca el botón Saltar (T)!",
  str_guide_warn_11800804 = "¡Nada mal! ¡Eres un jugador nato!",
  str_guide_warn_11800805 = "A continuación, tendremos que lidiar con un Eclipsite volador. ¡Después de rebotar, puedes atacar un Eclipsite en una posición más alta usando un doble salto!",
  str_guide_warn_11800806 = "Ahora, toque Saltar!",
  str_guide_warn_11800807 = "¡Toca Saltar de nuevo para usar tu ataque de doble salto!",
  str_guide_warn_11800808 = "¡Ya has dominado oficialmente los controles básicos del juego! ¡Intenta despejar esta etapa tú mismo!",
  str_guide_warn_11800901 = "Navegante, un pajarito me dice que te has estado quejando de que la primera etapa es demasiado fácil para ti.",
  str_guide_warn_11800902 = "Bueno, no te preocupes, ¡tengo nuevos monstruos aún más difíciles esperándote! ¡Es necesario saltar sobre estos Eclipsites con cabeza de casco dos veces antes de que puedas contarlos!",
  str_guide_warn_11800903 = "¡Toca Saltar y deshazte de ese casco!",
  str_guide_warn_11800904 = "¡Toca Bucear mientras estás en el aire para sumergirte rápidamente y eliminar al enemigo de abajo!",
  str_guide_warn_118009041 = "¡Golpea Dive (R) mientras estás en el aire para sumergirte rápidamente y eliminar al enemigo de abajo!",
  str_guide_warn_11800905 = "Consejo: Bucear no solo es bueno para atacar a los enemigos, sino que también te hace rebotar más alto, ¡así que puedes alcanzar a los enemigos en el cielo!",
  str_guide_warn_11800906 = "¡Este es el último consejo que te voy a dar! Estos eclipsitos espinosos no se pueden pisotear, así que cuando los veas, ¡evítalos saltando! Bueno, ¡ahora todo depende de ti, Navegante! ¡Buena suerte!",
  str_guide_warn_11801001 = "¡Ejejejeje! ¡Finalmente, es hora de que tome el centro del escenario! Conoce al jefe final: ¡Gronkenstein Ruu!",
  str_guide_warn_11801101 = "Esta es una de mis conchas de amor. Prométeme que no usarás Dive o Double Jump para reventarlo. ¡De lo contrario, no podré vencerte!",
  str_guide_warn_11801201 = "¡Ay! ¡¿En realidad desviaste mi caparazón e hiciste que me golpeara a mí?!",
  str_guide_warn_11801202 = "Tengo tanto HP... Si sigues golpeándome con proyectiles, yo... Oye, ¿¡por qué eres tan bueno en esto, navegante!? ¡Bien entonces! ¡Dale!",
  str_guide_warn_11900101 = "¡El evento Fantasma del Fuego ha comenzado! ¡Prepárate para investigar el misterioso caso y explorar la verdad detrás de él con tus amigos en Umbraton en Manhunt: The Blue Flame!",
  str_guide_warn_11900102 = "En Dark Alley Encounters nos enfrentaremos a una serie de difíciles desafíos.",
  str_guide_warn_11900103 = "Los registros de casos obtenidos al completar las etapas del evento y gastar Prism se pueden usar para canjear varias recompensas de Search & Seizure.",
  str_guide_warn_11900104 = "En el modo misterioso Midnight Scribbles, exploraremos los secretos del orfanato con jóvenes Hati!",
  str_guide_warn_11900105 = "¡Crash & Burn está de vuelta por tiempo limitado! ¡Prepárate para experimentar este juego único!",
  str_guide_warn_11900106 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_11900107 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_11900108 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_11900201 = "¡Bienvenido a Garabatos de medianoche! ¡Repasemos juntos nuestras experiencias pasadas en el orfanato!",
  str_guide_warn_11900202 = "¡Toca Recoger crayón para comenzar!",
  str_guide_warn_11900203 = "Si ya ha comenzado una aventura por el camino de la memoria, ¡toque aquí para continuar su viaje!",
  str_guide_warn_11900204 = "Las misiones y las recompensas se mostrarán en el álbum, ¡y también puedes ver los finales que has logrado!",
  str_guide_warn_11900205 = "Si hay algo que todavía no entiendes, puedes consultar la información aquí.",
  str_guide_warn_11900301 = "Este es un mapa del orfanato. ¡Tendremos que explorar por todas partes para encontrar inspiración!",
  str_guide_warn_11900302 = "La inspiración que encuentre se mostrará aquí. ¡Serán útiles más tarde!",
  str_guide_warn_11900303 = "¡Digamos hola a Miss Childminder!",
  str_guide_warn_11900304 = "¡Preguntémosle a Miss Childminder sobre este lugar!",
  str_guide_warn_11900401 = "¿Estás listo para hablar con Miss Childminder?",
  str_guide_warn_11900402 = "Aquí hay una lista de preguntas que puede hacer. ¡Algunos de ellos se pueden preguntar directamente, mientras que otros solo se pueden preguntar después de encontrar ciertas inspiraciones!",
  str_guide_warn_11900403 = "¡Hazle preguntas sobre este lugar!",
  str_guide_warn_11900404 = "¡Sigue haciendo preguntas mientras exploras para encontrar inspiración! ¡Podrás hacer más preguntas una vez que encuentres más inspiración!",
  str_guide_warn_11900501 = "Es tan desordenado aquí. ¡Vamos a investigar todo cuidadosamente!",
  str_guide_warn_11900502 = "¡Aquí se muestra que hay muchos objetos sospechosos en esta habitación!",
  str_guide_warn_11900503 = "Parece que no hay pistas. Centrémonos en observar primero.",
  str_guide_warn_11900504 = "Aquí hay un par de guantes extraños. ¡Acércate e inspecciónalo!",
  str_guide_warn_11900601 = "¡Repasemos la inspiración que hemos encontrado y recapitulemos primero los eventos de hoy!",
  str_guide_warn_11900602 = "Para resolver este misterio, necesitaremos tres piezas de inspiración para obtener la respuesta.",
  str_guide_warn_11900603 = "Esta es toda la inspiración que tienes. ¡Tienes que elegir los correctos!",
  str_guide_warn_11900604 = "En primer lugar, sobre este lugar... ¿Parece ser un hogar lleno de amor y cariño?",
  str_guide_warn_11900605 = "Después de eso, es obvio que los niños viven aquí con nosotros. ¡Hay muchos niños en el orfanato!",
  str_guide_warn_11900606 = "Finalmente, ¿somos buenos o malos? Aunque algunos de nosotros somos amables, también parece haber algunos malos aquí... Tendremos que identificarlos a todos con cuidado.",
  str_guide_warn_11900607 = "¡Intenta clasificar tu inspiración!",
  str_guide_warn_11900608 = "¡Éxito! ¡Así que así es la situación en el orfanato!",
  str_guide_name1 = "Firmado por...",
  str_guide_name2 = "Por favor escribe tu apodo",
  str_guide_name3 = "Confirmar",
  str_guide_name4 = "Tu apodo no tiene que ser tu nombre real, y no puede incluir caracteres especiales (máximo 14 caracteres)",
  str_guide_create_no_name = "Por favor, crea tu apodo primero",
  str_guide_ROLE_ERROR_DIRTY_NICK = "Contiene palabras prohibidas",
  str_guide_ROLE_ERROR_CHANGE_NICK_INVALID = "Los caracteres esp. no se pueden utilizar",
  str_guide_ROLE_ERROR_CHANGE_NICK_LIMIT = "La long. máxima de apodo es de 14 caracteres",
  str_guide_ROLE_ERROR_CHANGE_NICK_REPEAT = "Ya tienes un apodo",
  str_guide_ROLE_ERROR_CHANGE_NICK_SPE = "Los caracteres esp. no se pueden utilizar",
  str_guide_ROLE_ERROR_DUPLICATE_NICK = "Apodo duplicado con otros jugadores",
  str_guide_ROLE_ERROR_NEWSIGN_THE_SAME_AS_OLD = "No hay cambio en la nueva firma",
  str_guide_ROLE_ERROR_NEWNAME_THE_SAME_AS_OLD = "No hay cambio en el nuevo apodo",
  str_guide_moren_name = "Navegador",
  str_guide_team_limit_4001050 = "Esta aventura requiere que la Srta. Blanc esté presente. Por favor, toca la tarjeta de arriba para cambiar Aurorian desp.",
  str_guide_circle_click = "Toca en cualquier lugar para continuar",
  str_guide_circle_1_Lt = "El sistema de defensa auto. (ADS) es el legado de la era antigua. ¡Es potente y funciona automáticamente!",
  str_guide_circle_1_LtT = "Sistema de defensa auto. (ADS)",
  str_guide_circle_1_Rt = "El ADS gira auto. una vez cada ronda. Tal vez estos sean los viejos ajustes desde la antigüedad...",
  str_guide_circle_1_RtT = "Reglas de movimiento",
  str_guide_circle_1_Rb = "El ADS infligirá daño a cualquier objetivo dentro de las tres casillas frente a él.",
  str_guide_circle_1_RbT = "Alcance de daño",
  str_guide_circle_2_Lt = "El triturador es un Eclipsite común que posee un ATQ y PS poco frecuente.",
  str_guide_circle_2_LtT = "Triturador",
  str_guide_circle_2_Lb = "Tipo de cuerpo grande significa que recibirá daños en multicasillas. ¡Usa la conexión para llegar a las casillas circundantes tanto como sea posible!",
  str_guide_circle_2_LbT = "Consejos importantes",
  str_guide_circle_3_Lb = "Tiene un alto daño de ataque y es muy difícil de eliminar dentro de un corto período de tiempo. Asegúrate de recuperar PS a tiempo al encontrar este Eclipsite.",
  str_guide_circle_3_LbT = "Consejos importantes",
  str_guide_circle_3_Lt = "Un Eclipsite con habilidades de Ataque a Distancia que inflige daño a una sola unidad en su fila o columna.",
  str_guide_circle_3_LtT = "Probador",
  str_guide_circle_4_Lt = "Un Eclipsite único que invoca a un Dretcher al campo de batalla cada ronda, hasta un máximo de 5 Dretchers.",
  str_guide_circle_4_LtT = "Cría Eclipsite - ojo malvado",
  str_guide_circle_4_Rt = "El ojo malvado no puede causar daño por sí solo y es seguro al acercarse.",
  str_guide_circle_4_RtT = "Alcance de daño",
  str_guide_circle_4_Rb = "Si no puedes derrotarlo con prontitud, resultará en una batalla impred., ¡así que ten cuidado!",
  str_guide_circle_4_RbT = "Consejos importantes",
  str_guide_circle_5_Rt = "El punto de escape no está activado y, por lo tanto, no está disponible. Elimina a los Eclipsites para desb.",
  str_guide_circle_5_RtT = "Punto de Escape",
  str_guide_circle_6_Rt = "El punto de escape se ha desbloqueado. ¡Apresúrate y escapa del campo de batalla!",
  str_guide_circle_6_RtT = "Desbloqueado",
  str_guide_circle_7_Rb = "El terreno abisal obstaculizará los movimientos. Cuidado con los Eclipsites escondidos detrás del terreno abisal.",
  str_guide_circle_7_RbT = "Terreno abisal",
  ["str_guide_circle_2-1_Lt"] = "Un Eclipsite astuto que le gusta montar emboscadas de alta velocidad.",
  ["str_guide_circle_2-1_LtT"] = "Eclipsite de alta velocidad - Carrera",
  ["str_guide_circle_2-1_Lb"] = "Debido a su enorme alcance de mov., es fácil para que se escabulla, ¡así que ten cuidado!",
  ["str_guide_circle_2-1_LbT"] = "Alcance de ataque",
  ["str_guide_circle_2-2_Lt"] = "Se dice que es un cristal de luz que apareció después del antiguo cataclismo. Puede convocar meteoritos peligrosos.",
  ["str_guide_circle_2-2_LtT"] = "Cristal de luz - Meteorito",
  ["str_guide_circle_2-2_Rt"] = "Inflige daño equivalente a un porcentaje de Max PS a un solo enemigo. Muy efectivo.",
  ["str_guide_circle_2-2_RtT"] = "Efectos especiales",
  ["str_guide_circle_2-3_Lt"] = "Se dice que es un cristal de luz que apareció después del antiguo cataclismo. Puede convocar los rayos peligrosos.",
  ["str_guide_circle_2-3_LtT"] = "Cristal de luz - Rayo",
  ["str_guide_circle_2-3_Rt"] = "Inflige daño equivalente a un porcentaje de Max PS a todos los enemigos. Muy efectivo.",
  ["str_guide_circle_2-3_RtT"] = "Efectos especiales",
  ["str_guide_circle_2-3-2_Rt"] = "El terreno especial que aparece al azar en el campo de batalla, puede ser aplastado con un combo en cadena de alcance.",
  ["str_guide_circle_2-3-2_RtT"] = "Trampa especial - Piedritas",
  ["str_guide_circle_2-3-2_Rb"] = "¡Las recom. especiales pueden dejar de aplastarlo!",
  ["str_guide_circle_2-3-2_RbT"] = "Efecto piedritas",
  ["str_guide_circle_2-7_Lt"] = "Un Eclipsite que usa ambos brazos para ataques dobles, que se ocupan de un daño muy alto.",
  ["str_guide_circle_2-7_LtT"] = "Eclipsite Alto ATQ - Segador",
  ["str_guide_circle_2-7_Rt"] = "El rango de ataque de Eclipsites de alto ATQ no es muy grande, por lo que solo tenga cuidado de evitarlos.",
  ["str_guide_circle_2-7_RtT"] = "Alcance de ataque",
  ["str_guide_circle_2-7_Rb"] = "Asegúrate de perm. lo más lejos posible de los Eclipsites de Alto ATQ, que infligen cant. masivas de daño con cada ataque.",
  ["str_guide_circle_2-7_RbT"] = "Consejos importantes",
  ["str_guide_circle_2-8_Rt"] = "El sistema de detonación inflige daño a 1 cúmulo circundante después de 2 rondas. ¡Mantente alejado de eso!",
  ["str_guide_circle_2-8_RtT"] = "Sistema de detonación",
  ["str_guide_circle_2-8_Rb"] = "El daño explosivo no discrimina entre amigo y enemigo, ¡así que haz tu estrategia basada en el movimiento de los Eclipsites!",
  ["str_guide_circle_2-8_RbT"] = "Consejos importantes",
  ["str_guide_circle_2-10_Lt"] = "Spellhound es una especie de monstruo especial que naturalmente tiene 3 capas de escudo.",
  ["str_guide_circle_2-10_LtT"] = "Monstruo Escudo - Spellhound",
  ["str_guide_circle_2-10_Rt"] = "El escudo solo desap. después de 3 ataques, así que mantente más cerca de él.",
  ["str_guide_circle_2-10_RtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_2-10_Rb"] = "¡El escudo de Spellhound se recupera en pocas rondas, así que ataca intensamente para derrotarlo!",
  ["str_guide_circle_2-10_RbT"] = "Consejos importantes",
  ["str_guide_circle_2-13_Lt_Red"] = "Los Aurorians Acuáticos infligen más daño a los enemigos de Fuego.",
  ["str_guide_circle_2-13_LtT_Red"] = "Agua contrarresta Fuego",
  ["str_guide_circle_2-13_Lt_Yellow"] = "Los Aurorians Acuáticos infligen menos daño a los enemigos de Trueno.",
  ["str_guide_circle_2-13_LtT_Yellow"] = "El Agua está siendo contrarrestada por el Trueno",
  str_guide_circle_None = "Los tipos no elementales no pueden ser contrarrestados por otros elementos, pero tampoco pueden contrarrestarlos.",
  ["str_guide_circle_2-10-1_Lt"] = "Contiene importante información robada y solo la soltará cuando lo maten.",
  ["str_guide_circle_2-10-1_LtT"] = "Eclipsites Intel",
  ["str_guide_circle_2-10-1_Rt"] = "¡Recoge la info. de inmediato después de matar el Datascite, o de lo contrario, podría ser robado!",
  ["str_guide_circle_2-10-1_RtT"] = "Consejos importantes",
  ["str_guide_circle_ex1-2_Lt"] = "Equipado con agujas paralizantes, puede atacar el primer objetivo en su camino a una vel. extremadamente alta cuando se activa.",
  ["str_guide_circle_ex1-2_LtT"] = "Balista de parálisis",
  ["str_guide_circle_ex1-2_Lb"] = "La penetración no es lo suficientemente fuerte. Ataca solo el primer objetivo único delante, provocado por una trampa.",
  ["str_guide_circle_ex1-2_LbT"] = "Alcance de ataque",
  ["str_guide_circle_ex1-3_Lt"] = "Equipado con hologramas especiales, puede esquivar efectivamente todo tipo de ataques.",
  ["str_guide_circle_ex1-3_LtT"] = "Fuerza espejismo",
  ["str_guide_circle_ex1-3_Rt"] = "Espejismo transmitirá a una distancia después de atacar y es difícil aniquilar por completo.",
  ["str_guide_circle_ex1-3_RtT"] = "Migración de alta velocidad",
  ["str_guide_circle_ex1-3_Rb"] = "La Parálisis de Balista puede contrarrestar efectivamente las habilidades de esquivar del Espejismo.",
  ["str_guide_circle_ex1-3_RbT"] = "Consejos importantes",
  ["str_guide_circle_ex1-4_Lt"] = "Equipado con agujas tóxicas, ataca el primer objetivo frente a él.",
  ["str_guide_circle_ex1-4_LtT"] = "Veneno especial M52",
  ["str_guide_circle_ex1-4_Lb"] = "La penetración no es lo suficientemente fuerte. Ataca solo el primer objetivo único delante, provocado por una trampa.",
  ["str_guide_circle_ex1-4_LbT"] = "Alcance de ataque",
  ["str_guide_circle_ex1-6_Rt"] = "Extremadamente ágil, se teletransporta a otra ubicación después de atacar y es capaz de convocar a un clon.",
  ["str_guide_circle_ex1-6_RtT"] = "Phantom",
  ["str_guide_circle_ex1-6_Rb"] = "Ataque a distancia en cruz, mientras con Rabia(PS cae al 25%), inflige daño en toda la pantalla.",
  ["str_guide_circle_ex1-6_RbT"] = "Alcance de ataque",
  ["str_guide_circle_ex2-4_Lb"] = "Los ataques normales avientan al objetivo una casilla. ¡También tiene una gran movilidad! ¡Ten cuidado!",
  ["str_guide_circle_ex2-4_LbT"] = "Eclipsite Aventador",
  ["str_guide_circle_ex2-4_Rb"] = "¡No solo los Eclipsites pueden derramar objetivos Aurorians, también pueden derramar explosivos!",
  ["str_guide_circle_ex2-4_RbT"] = "Consejos especiales",
  ["str_guide_circle_ex4-2_Lb"] = "Se mueve a gran velocidad, haciéndolo casi imposible de golpear. También conocido como \"Espíritu.\"",
  ["str_guide_circle_ex4-2_LbT"] = "Parpadeo",
  ["str_guide_circle_ex4-2_Rb"] = "Cambia de posición antes de atacar en cada ronda.",
  ["str_guide_circle_ex4-2_RbT"] = "Patrón de acción",
  ["str_guide_circle_ex4-2_Rt"] = "Usa a los Aurorians Francotiradores para entrar al rango de ataque.",
  ["str_guide_circle_ex4-2_RtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_ex4-6_Lb"] = "Esta variante de Flicker es muy ágil, como una ilusión que va y viene sin dejar rastro.",
  ["str_guide_circle_ex4-6_LbT"] = "Sin forma",
  ["str_guide_circle_ex4-6_Rb"] = "Cambia su posición antes de atacar en cada ronda. Y convoca a una gran cantidad de No-entidades al campo de batalla.",
  ["str_guide_circle_ex4-6_RbT"] = "Patrón de acción",
  ["str_guide_circle_ex4-6_Rt"] = "Elimina las No Entidades del campo de batalla y utiliza las habilidades de conversión de casillas para acercarte rápidamente a los Sin Forma e infligirles daño.",
  ["str_guide_circle_ex4-6_RtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_2-3-1_Lt"] = "Una versión modificada de una trampa de perforación de alta velocidad, con una cabeza de gancho curvo que inflige gran daño, pero con una penetración más débil.",
  ["str_guide_circle_2-3-1_LtT"] = "Cohete especial SX-3",
  ["str_guide_circle_2-3-1_Lb"] = "Ataca el primer objetivo único delante, se activa una vez por ronda.",
  ["str_guide_circle_2-3-1_LbT"] = "Alcance de ataque",
  ["str_guide_circle_2-11_Lb"] = "Mientras dura la corrosión, Eve no puede moverse ni atacar y necesita protección.",
  ["str_guide_circle_2-11_LbT"] = "Eve",
  ["str_guide_circle_3-1_Lt"] = "Realiza curación total, muy problemática.",
  ["str_guide_circle_3-1_LtT"] = "Eclipsite Sanador",
  ["str_guide_circle_3-1_Lb"] = "No nos atacará. De hecho, intentará manterse alejado de objetivos peligrosos.",
  ["str_guide_circle_3-1_LbT"] = "Características de comportamiento",
  ["str_guide_circle_3-4_Lt"] = "Sus ataques contundentes infligen daño aturden al objetivo.",
  ["str_guide_circle_3-4_LtT"] = "Eclipsite Aturdir",
  ["str_guide_circle_3-4_Lb"] = "Su alcance de ataque no es enorme, por lo que puedes enc. una manera de recorrerlo. Pero no debes acercarte a él.",
  ["str_guide_circle_3-4_LbT"] = "Alcance de ataque",
  ["str_guide_circle_3-4_Rb"] = "Parece que sus músculos se concentran en sus manos, ¿¡con un cerebro tan lindo pero pequeño!?",
  ["str_guide_circle_3-4_RbT"] = "Notas adicionales",
  ["str_guide_circle_3-7_Lt"] = "Después de que el Eclipsite se mueva, Plaga de Picos aparecerá a lo largo de su sendero, infligiendo daños a los que lo pisan.",
  ["str_guide_circle_3-7_LtT"] = "Eclipsite Plaga de Picos",
  ["str_guide_circle_3-7_Lb"] = "Los Eclipsites tienen una fuerte movilidad y cubrirán todo el campo de batalla con Plaga de picos desp. de unas pocas rondas.",
  ["str_guide_circle_3-7_LbT"] = "Estrategia de Acción",
  ["str_guide_circle_3-10_Lt"] = "Remolino es una casilla de teletransportación espacial que puede transportar cualquier cosa al otro lado del Remolino.",
  ["str_guide_circle_3-10_LtT"] = "Remolino",
  ["str_guide_circle_3-10_Lb"] = "Los combos en cadenas de los Aurorians serán transportados al otro lado del Remolino. Intenta aprovechar esto.",
  ["str_guide_circle_3-10_LbT"] = "Estrategia especial",
  ["str_guide_circle_3-10_Rb"] = "Dicen que algunos Remolinos pueden enviarte a otro mundo... ¡Eso ni siq. es gracioso!",
  ["str_guide_circle_3-10_RbT"] = "Consejos especiales",
  ["str_guide_circle_4-1_Lt"] = "Puede invocar runas en el suelo, que invocarán Eclipsites Sanadores después de 2 rondas.",
  ["str_guide_circle_4-1_LtT"] = "Eclipsite Runa",
  ["str_guide_circle_4-1_Lb"] = "Pasa en la runa para eliminarla, pero asegúrate de planificar tu camino con anticipación.",
  ["str_guide_circle_4-1_LbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_4-1_Rb"] = "Eclipsites Runa son lentos, así que puedes perseguirlas y matarlas rápidamente.",
  ["str_guide_circle_4-1_RbT"] = "Consejos especiales",
  ["str_guide_circle_4-7_Lt"] = "Un Eclipsite que puede absorber las casillas circundantes del mismo elemento para atacar, tratar un gran daño.",
