  ["str_guide_circle_N1_1-1_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N1_1-8_Lb"] = "Liberar Daño de Área Grande.",
  ["str_guide_circle_N1_1-8_LbT"] = "Dawn",
  ["str_guide_circle_N1_1-8_Rb"] = "Convoca un Dawn Sprite, Dawn restaura PS cuando Dawn Sprite está cerca.",
  ["str_guide_circle_N1_1-8_RbT"] = "Consejos importantes",
  ["str_guide_circle_N1_2-1_Lb"] = "Liberar Daño de Área Grande.",
  ["str_guide_circle_N1_2-1_LbT"] = "Eve",
  ["str_guide_circle_N1_2-1_Rb"] = "Eve genera un escudo para ella misma para resistir el daño.",
  ["str_guide_circle_N1_2-1_RbT"] = "Consejos importantes",
  ["str_guide_circle_N1_2-2_Lb"] = "La aflicción de Eve la incapacita para actuar temporalmente.",
  ["str_guide_circle_N1_2-2_LbT"] = "Eve",
  ["str_guide_circle_N1_2-2_Rb"] = "Protege a Eve de ataques de Eclipsites.",
  ["str_guide_circle_N1_2-2_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N1_2-3_Lb"] = "Eve no será atacada por Eclipsites y restaura PS a los aliados cercanos continuamente.",
  ["str_guide_circle_N1_2-3_LbT"] = "Eve",
  ["str_guide_circle_N1_2-3_Rb"] = "Resiste ataques de Eclipsites con ayuda de Eve y reclama la victoria.",
  ["str_guide_circle_N1_2-3_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N3_1-1_LbT"] = "Caballero caído",
  ["str_guide_circle_N3_1-1_Lb"] = "Ataca según las reglas de movimiento de un caballo de ajedrez.",
  ["str_guide_circle_N3_1-1_RbT"] = "Consejos importantes",
  ["str_guide_circle_N3_1-1_Rb"] = "Asegúrate de no pararte en un lugar donde un Caballero Caído pueda caer, si no, serás aturdido.",
  ["str_guide_circle_N3_1-3_LbT"] = "Torre Enfurecida",
  ["str_guide_circle_N3_1-3_Lb"] = "Ataca según las reglas de movimiento de una torre en el ajedrez. Ataca horizontal o verticalmente.",
  ["str_guide_circle_N3_1-3_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N3_1-3_Rb"] = "Intenta usar obstáculos para realizar ataques indirectos en Torres Enfurecidas.",
  ["str_guide_circle_N3_1-5_LbT"] = "Obispo de Eclipse",
  ["str_guide_circle_N3_1-5_Lb"] = "Se mueve en diagonal de acuerdo con las reglas de movimiento de un alfil en el ajedrez. Ataca horizontal o verticalmente.",
  ["str_guide_circle_N3_1-5_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N3_1-5_Rb"] = "Utiliza los obstáculos a tu favor cuando intentes evitar ataques de un Obispo de Eclipse.",
  ["str_guide_circle_N3_1-7_LtT"] = "Reina Engañosa",
  ["str_guide_circle_N3_1-7_Lt"] = "Ataca de acuerdo con las reglas de movimiento de una reina en el ajedrez, causando daño severo a objetivos a su alcance. Si los objetivos están fuera de alcance, espera en silencio la oportunidad de atacar.",
  ["str_guide_circle_N3_1-7_RtT"] = "Consejos importantes",
  ["str_guide_circle_N3_1-7_Rt"] = "Ten cuidado de no permanecer dentro del rango de alerta temprana de la Reina Engañosa, si no puedes esperar recibir una gran cantidad de daño.",
  ["str_guide_circle_N3_1-9_LtT"] = "Peón Perdido",
  ["str_guide_circle_N3_1-9_Lt"] = "Avanza en cada ronda, dando un golpe de salto. Después de llegar al borde inferior izquierdo del tablero, se asciende a otra pieza en el siguiente orden: Torre, Caballo, Alfil, Reina.",
  ["str_guide_circle_N3_1-9_RtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N3_1-9_Rt"] = "Evade al peón perdido - los ataques de CAMPEÓN y derrótalo antes de ser promovido.",
  ["str_guide_circle_N3_1-20_LbT"] = "Monarca desolado",
  ["str_guide_circle_N3_1-20_Lb"] = "Controlador de monstruos del ajedrez. Un maestro estratega que sobresale en el mando de sus tropas y obliga al enemigo a jugar a su favor.",
  ["str_guide_circle_N3_1-20_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N3_1-20_Rb"] = "Obliga al tablero a bajar una casilla en cada ronda, acelerando la transformación de sus Peones Perdidos. Elimina todos los peones perdidos del tablero lo antes posible y presta atención a la posición de cada pieza en cada ronda.",
  ["str_guide_circle_N5_1-3_LtT"] = "Abismo",
  ["str_guide_circle_N5_1-3_Lt"] = "Después de algunas rondas, él libera su poder interno para autodestrucción, y destrucción del terreno.",
  ["str_guide_circle_N5_1-3_RtT"] = "Casillas Dañadas",
  ["str_guide_circle_N5_1-3_Rt"] = "Casillas dañadas no pueden ser usadas por Aurorians.",
  ["str_guide_circle_N5_1-3_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N5_1-3_Rb"] = "¡Derrota el Abismo antes que él explote!",
  ["str_guide_circle_N5_1-10_LbT"] = "Hylingerr",
  ["str_guide_circle_N5_1-10_Lb"] = "Un monstruo gigante que es tan astuto como poderoso. Inflige daño severo a los objetivos a su alcance y tiene la capacidad de registrar posiciones de los objetivos.",
  ["str_guide_circle_N5_1-10_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N5_1-10_Rb"] = "Este monstruo es relativamente voluminoso. Presta atención a tu posición para evitar daño.",
  ["str_guide_circle_N6_1-10_LtT"] = "Mirren Gautier",
  ["str_guide_circle_N6_1-10_Lt"] = "Un noble caído, su poder crece a medida que su odio por Lumopolis se profundiza...",
  ["str_guide_circle_N6_1-10_RtT"] = "Esconder",
  ["str_guide_circle_N6_1-10_Rt"] = "Puede esconderse cuando está sobre casillas rotas, volviéndose inmune al daño de los ataques normales y habilidades direccionales.",
  ["str_guide_circle_N6_1-10_LbT"] = "Resentimiento",
  ["str_guide_circle_N6_1-10_Lb"] = "Puede teletransportarse varias veces y romper casillas en el campo de batalla cuando el enemigo no está dentro del alcance de ataque.",
  ["str_guide_circle_N6_1-10_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N6_1-10_Rb"] = "¡Elimina las casillas rotas antes de atacar!",
  ["str_guide_circle_N6_1-1_LtT"] = "Gusano del Manto",
  ["str_guide_circle_N6_1-1_Lt"] = "Un Eclipsite que una vez habitó en las profundidades del Territorio Secreto, sobresale en lanzar ataques desde el subsuelo. También se dice que puede cavar pasajes subterráneos para otras Eclipsites.",
  ["str_guide_circle_N6_1-1_RtT"] = "Nota",
  ["str_guide_circle_N6_1-1_Rt"] = "Sobresale en la utilización de terrenos destrozados, y posee la capacidad de infligir un gran daño a las unidades que se encuentran alrededor de las casillas rotas.",
  ["str_guide_circle_N6_1-1_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N6_1-1_Rb"] = "¡Controla la cantidad de casillas rotas en el campo de batalla y presta atención a tu posición!",
  ["str_guide_circle_N7_1-10_LtT"] = "Maude Solus",
  ["str_guide_circle_N7_1-10_Lt"] = "Se somete a una peligrosa transformación temporal sin pensarlo dos veces para obtener un nuevo poder.",
  ["str_guide_circle_N7_1-10_RtT"] = "Marioneta Solus",
  ["str_guide_circle_N7_1-10_Rt"] = "Puede invocar constantemente Eclipsites para ayudar en la batalla.",
  ["str_guide_circle_N7_1-10_LbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N7_1-10_Lb"] = "¡Evita que Maude invoque Eclipsites y atácalo directamente!",
  ["str_guide_circle_N7_1-4_LbT"] = "¡Mantente alerta!",
  ["str_guide_circle_N7_1-4_Lb"] = "¡Los Eclipsites que se transformaron después de tomar \"potenciadores\" parecen completamente diferentes a los que estamos acostumbrados a tratar! ¡Por favor, ten cuidado!",
  ["str_guide_circle_N9_1-3_LbT"] = "¿¿¿???",
  ["str_guide_circle_N9_1-3_Lb"] = "Eclipsite enigmático de origen desconocido, cuya presencia no parece ajustarse a la realidad que conoces.",
  ["str_guide_circle_N9_1-3_RbT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N9_1-3_Rb"] = "Cuando no está en Hora de Aurora, obtiene una reducción significativa del daño.",
  ["str_guide_circle_N9_1-3_LtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N9_1-3_Lt"] = "¡Ataca al monstruo durante la Hora de Aurora!",
  ["str_guide_circle_N9_1-10_LbT"] = "Traficante de Miedo",
  ["str_guide_circle_N9_1-10_Lb"] = "El polvo se ha asentado y la identidad de un enemigo familiar pero extraño está a punto de ser revelada. Es hora de demostrar tu determinación.",
  ["str_guide_circle_N9_1-10_RbT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N9_1-10_Rb"] = "Cuando no está en Hora de Aurora, obtiene una reducción significativa del daño. Capaz de convocar minions para ayudar en la batalla.",
  ["str_guide_circle_N9_1-10_LtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N9_1-10_Lt"] = "¡Elimina a los Súbdito y ataca a Traficante de Miedo con la mayor frecuencia posible durante Hora de Aurora!",
  ["str_guide_circle_N11_1-3_LtT"] = "bloqueador yo",
  ["str_guide_circle_N11_1-3_Lt"] = "Una trampa misteriosa de la Ciudad Perdida. Parece ser un prototipo temprano de Jammer.",
  ["str_guide_circle_N11_1-3_RtT"] = "Características de la trampa",
  ["str_guide_circle_N11_1-3_Rt"] = "Con su capacidad para interrumpir el área circundante, los aurorianos reciben daño cuando se mueven alrededor.",
  ["str_guide_circle_N11_1-3_LbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N11_1-3_Lb"] = "¡Cuidado de no acercarse al Jammer cuando se mueve!",
  ["str_guide_circle_N11_1-12_LbT"] = "Valencia",
  ["str_guide_circle_N11_1-12_Lb"] = "Las identidades de los residentes de la Ciudad Perdida siguen siendo un misterio.",
  ["str_guide_circle_N11_1-12_RbT"] = "¡Cuidado!",
  ["str_guide_circle_N11_1-12_Rb"] = "Valencia es capaz de convocar y controlar poderosas trampas para ayudarla en la batalla. ¡Cuidado con sus trampas por ahí!",
  ["str_guide_circle_N12_1-1_LbT"] = "Gatitopus",
  ["str_guide_circle_N12_1-1_Lb"] = "Una compañera especial de Gretel. Se parece a un gato con muchas patas... Es lindo, pero algo inquietante.",
  ["str_guide_circle_N12_1-1_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N12_1-1_Rb"] = "Tentaclaw puede transferir el daño sufrido al cuerpo principal. Esta función se puede usar para contrarrestar monstruos.",
  ["str_guide_circle_N12_1-2_LbT"] = "Pisotón de hierro",
  ["str_guide_circle_N12_1-2_Lb"] = "Una compañera especial de Gretel. Tiene un par de patas extremadamente fuertes que pueden repeler a cualquier enemigo.",
  ["str_guide_circle_N12_1-2_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N12_1-2_Rb"] = "Ironstomp es un hábil triturador de azulejos. Trae aurorianos que conviertan mosaicos para contrarrestarlo.",
  ["str_guide_circle_N12_1-3_LbT"] = "Basilisco",
  ["str_guide_circle_N12_1-3_Lb"] = "Una compañera especial de Gretel. Juguetón y enérgico, disfruta especialmente luchando contra un grupo de enemigos.",
  ["str_guide_circle_N12_1-3_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N12_1-3_Rb"] = "Detrás de la piel áspera de Basilisk hay un corazón tierno. Las habilidades de control probablemente funcionen bien.",
  ["str_guide_circle_N12_1-4_LbT"] = "Puercoespín",
  ["str_guide_circle_N12_1-4_Lb"] = "Una compañera especial de Gretel. Generalmente tranquilo y plácido, pero se sabe que se vuelve loco en la batalla. Aproximación con precaución.",
  ["str_guide_circle_N12_1-4_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N12_1-4_Rb"] = "Spikeyhog está cubierto de púas. Lo mejor para los aurorianos es mantener la distancia.",
  ["str_guide_circle_N13_1-1_LbT"] = "espada del inframundo",
  ["str_guide_circle_N13_1-1_Lb"] = "Exjefe de los Wisp que se dedica a luchar contra los invasores de Cloud Island.",
  ["str_guide_circle_N13_1-1_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N13_1-1_Rb"] = "Sword of the Underworld tomará diferentes decisiones tácticas según su distancia de los aurorianos. Manténgase alejado de ella para ganar capacidad de recuperación y lidiar mejor con sus ataques.",
  ["str_guide_circle_N14_1-1_LbT"] = "Nagi - Hoja de furia",
  ["str_guide_circle_N14_1-1_Lb"] = "La frenética Nagi atacará a cualquiera que perciba como un intruso.",
  ["str_guide_circle_N14_1-1_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N14_1-1_Rb"] = "Observa la secuencia de ataque de Nagi - Fury Blade para evitar el daño letal y el contraataque cuando surja la oportunidad.",
  ["str_guide_circle_N13_1-12_LbT"] = "Fujikumo Nobutora",
  ["str_guide_circle_N13_1-12_Lb"] = "Un tirano que vino de otra isla del Lejano Oriente para gobernar Cloud Island, y hará cualquier cosa para declarar su soberanía sobre ella.",
  ["str_guide_circle_N13_1-12_RbT"] = "¡Cuidado!",
  ["str_guide_circle_N13_1-12_Rb"] = "Fujikumo Nobutora puede invocar una gran cantidad de fantasmas para que lo ayuden en la batalla.",
  ["str_guide_circle_N13_1-12_LtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N13_1-12_Lt"] = "Despeja los fantasmas en el campo de batalla a tiempo.",
  ["str_guide_circle_N14_1-12_LbT"] = "Fujikumo Nobutora - Devorar",
  ["str_guide_circle_N14_1-12_Lb"] = "Debido a su obsesión, se convirtió en un hombre horrible y prometió eliminar a todos los que se resistieran.",
  ["str_guide_circle_N14_1-12_RbT"] = "¡Advertencia!",
  ["str_guide_circle_N14_1-12_Rb"] = "Fujikumo Nobutora - Devour lanzará diferentes habilidades según la posición de los aurorianos.",
  ["str_guide_circle_N14_1-12_LtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N14_1-12_Lt"] = "Cuando estés en batalla, recuerda colocarte con cuidado y contraatacar apropiadamente.",
  ["str_guide_circle_N13_1-2_LbT"] = "Fantasma",
  ["str_guide_circle_N13_1-2_Lb"] = "Un monstruo especial del Lejano Oriente que se dice que \"ni está vivo ni muerto\" y es extremadamente hostil hacia los vivos.",
  ["str_guide_circle_N13_1-2_RbT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N13_1-2_Rb"] = "Sus habilidades de lucha pueden no ser temibles, pero su número sí lo es.",
  str_guide_fail_1 = "Nutrir Aurorians",
  str_guide_fail_2 = "Subir los niveles y ascender los Aurorians son formas de impulsar mucho las habilidades Aurorians",
  str_guide_fail_3 = "Aurorians que se pueden mejorar:",
  str_guide_fail_4 = "Obtén materiales de crianza",
  str_guide_fail_5 = "Obtén materiales de EXP Aurorian y materiales de avance de las siguientes maneras",
  str_guide_fail_6 = "Obtenido de: Etapas de Recursos de Nieve Olvidada y Etapas Principales",
  str_guide_fail_7 = "Toca en cualquier lugar para saltar",
  str_guide_warn_level_speed = "ADVERTENCIA ¡Debes subir de nivel!",
  str_guide_fail_8 = "Etapa fallida",
  str_guide_warn_40096 = "Toca aquí",
  str_guide_fail_9 = "Familiarízate con las Habilidades de cada pieza",
  str_guide_fail_10 = "Aprende las características de cada pieza y saca todo su potencial.",
  str_guide_fail_11 = "Ajustar las estrategias de combate",
  str_guide_fail_12 = "Cada enemigo sigue un patrón de movimiento fijo. Ajusta tu estrategia de combate en consecuencia.",
  ["str_guide_circle_N17_1-14_LtT"] = "Claudia",
  ["str_guide_circle_N17_1-14_Lt"] = "La IA en la base subterránea de Eraveil que ha estado protegiendo la base durante miles de años y es responsable de eliminar a todos los enemigos invasores.",
  ["str_guide_circle_N17_1-14_RbT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N17_1-14_Rb"] = "Resiste perfectamente los ataques normales cuando está parado en la plataforma o arriba Asher, salta inmediatamente a otra plataforma dentro de 2 grupos en el momento en que se aplasta la que está debajo de tus pies.",
  ["str_guide_circle_N17_1-14_LbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N17_1-14_Lb"] = "Usa Sniper para acertar directamente Claudia, también tenga cuidado de no destruir la plataforma.",
  ["str_guide_circle_N17_2-14_LtT"] = "Asher",
  ["str_guide_circle_N17_2-14_Lt"] = "La IA en la base subterránea de Eraveil que parece grande y pesada, es Claudiaamigo de",
  ["str_guide_circle_N17_2-14_RbT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N17_2-14_Rb"] = "Muestra rasgos de inmortalidad y se levantará poco después de ser derribado, pero la cantidad de HP restaurado disminuye con cada derribo.",
  ["str_guide_circle_N17_2-14_LbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N17_2-14_Lb"] = "Sortea este poderoso escudo y derrota Claudia lo antes posible.",
  ["str_guide_circle_N18_1-12_LtT"] = "Minos",
  ["str_guide_circle_N18_1-12_Lt"] = "El mayordomo de la medalla de oro de Andersen que no deja manchas, basura o alimañas desatendidas.",
  ["str_guide_circle_N18_1-12_RtT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N18_1-12_Rt"] = "Minos cambiará entre el Estado Mortal y el Estado Minotauro en función de su pila de Marcas. Restablece todas las fichas que pasa a fichas mejoradas o debilitadas según su estado.",
  ["str_guide_circle_N18_1-12_RbT"] = "¡Advertencia!",
  ["str_guide_circle_N18_1-12_Rb"] = "La mayoría de los ataques de Minos se vuelven más fuertes a medida que gana más acumulaciones de su marca. Cuantas más pilas de marcas tenga y más mosaicos mejorados en el campo, más peligrosos se vuelven sus ataques.",
  ["str_guide_circle_N18_1-1_LtT"] = "Baldosa debilitada",
  ["str_guide_circle_N18_1-1_Lt"] = "Los mosaicos especiales opuestos a los mosaicos mejorados pueden reducir el daño causado por las conexiones del jugador.",
  ["str_guide_circle_N18_1-1_RbT"] = "Características",
  ["str_guide_circle_N18_1-1_Rb"] = "Los Aurorianos que pasen recibirán una desventaja de reducción de daño de conexión 2 veces mayor que la de una ficha normal.",
  ["str_guide_circle_N20_1-12_LtT"] = "guardián del núcleo",
  ["str_guide_circle_N20_1-12_Lt"] = "Un guardián gigantesco que protege el núcleo de energía de la nave. Se despertará y luchará cuando el Núcleo esté bajo amenaza.",
  ["str_guide_circle_N20_1-12_LbT"] = "Características del lugar",
  ["str_guide_circle_N20_1-12_Lb"] = "Cuando Core Guardian está despierto, rotará el lado del cubo mágico lejos del jugador al final de cada ronda, cambiando la distribución de monstruos en el campo.",
  ["str_guide_circle_N20_1-12_RbT"] = "Debilidades del monstruo",
  ["str_guide_circle_N20_1-12_Rb"] = "El módulo de congelación es la debilidad del Guardián. Derrotar el módulo de congelación paralizará al guardián del núcleo durante 1 asalto y hará que sea más fácil lastimarlo.",
  str_guide_warn_5193011 = "Los personajes de P5R Collab entran en la batalla con sus habilidades especiales.",
  str_guide_warn_5193012 = "Toca aquí para ver la descripción de la habilidad.",
  str_guide_warn_5193013 = "Inicia la habilidad especial y acaba con estos enemigos de una sola vez.",
  ["str_guide_circle_N22_1-10_LtT"] = "Casta",
  ["str_guide_circle_N22_1-10_Lt"] = "Aparentemente distante, pero en realidad muy responsable. Se asoció con Pollux para formar el dúo de mercenarios llamado \"Raven's Blood\" para defender mejor a los niños que viven en la iglesia.",
  ["str_guide_circle_N22_1-10_RbT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N22_1-10_Rb"] = "Lanza diferentes ataques de habilidad según las posiciones de los aliados; puede contrarrestar habilidades activas aliadas.",
  ["str_guide_circle_N22_1-10_LbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N22_1-10_Lb"] = "Vigila las posiciones relativas de ambos lados; controla la frecuencia de liberación de habilidades activas.",
  ["str_guide_circle_sailing_1-1_LtT"] = "Gusano",
  ["str_guide_circle_sailing_1-1_Lt"] = "Aunque no está claro cómo funciona, seguirán apareciendo eclipses. La batalla probablemente se volverá muy difícil si no se resuelve lo antes posible.",
  ["str_guide_circle_sailing_1-1_RbT"] = "Características",
  ["str_guide_circle_sailing_1-1_Rb"] = "Si se abre Wormgate, se invocarán Eclipsites al comienzo de la siguiente ronda.",
  ["str_guide_circle_sailing_1-1_RtT"] = "¡Advertencia!",
  ["str_guide_circle_sailing_1-1_Rt"] = "Si un Eclipsite está parado sobre el Wormgate al comienzo de la ronda, el Wormgate no invocará nuevos Eclipsites en esta ronda.",
  ["str_guide_circle_sailing_2-1_LtT"] = "Halo de piedra",
  ["str_guide_circle_sailing_2-1_Lt"] = "Rocas con Lumina desconocida, comúnmente presentes en ruinas, se rumorea que cambian la Lumina a su alrededor.",
  ["str_guide_circle_sailing_2-1_RbT"] = "Características",
  ["str_guide_circle_sailing_2-1_Rb"] = "Al comienzo de cada ronda de jugador, Halo Stone convierte todas las fichas de un elemento diferente dentro de un rango determinado en el mismo elemento.",
  ["str_guide_circle_sailing_2-1_RtT"] = "Estrategia",
  ["str_guide_circle_sailing_2-1_Rt"] = "El elemento de Halo Stone siempre será el mismo que el elemento del mosaico en el que se encuentra. Nuestros aliados pueden usar esto para aprovechar la ventaja en la batalla.",
  ["str_guide_circle_sailing_2-2_RbT"] = "¡Advertencia!",
  ["str_guide_circle_sailing_2-2_Rb"] = "Si el mosaico debajo de Halo Stone se convierte en un mosaico cromático, Halo Stone será destruido.",
  ["str_guide_circle_sailing_2-3_LtT"] = "Estela de prohibición de habilidades",
  ["str_guide_circle_sailing_2-3_Lt"] = "Una estela corta y misteriosa encontrada en ciertas ruinas. Las runas imponen ciertas restricciones a los atacantes.",
  ["str_guide_circle_sailing_2-3_RbT"] = "Características",
  ["str_guide_circle_sailing_2-3_Rb"] = "Silencia a todos los Aurorianos dentro de un cierto rango, haciéndolos incapaces de usar habilidades activas.",
  ["str_guide_circle_sailing_2-4_LtT"] = "Estrategia",
  ["str_guide_circle_sailing_2-4_Lt"] = "Usa una habilidad combinada en cadena o una habilidad activa que inflija daño de área para infligir daño a las estelas de prohibición de habilidades. Se romperán después de recibir una cierta cantidad de daño.",
  ["str_guide_circle_N22_2-1_LtT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N22_2-1_Lt"] = "Puede usar torretas para infligir daño continuo al enemigo y ahuyentar a cualquier enemigo que se le acerque demasiado. La guardia se fortalecerá cuando perciba una gran amenaza.",
  ["str_guide_circle_N22_2-1_RtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N22_2-1_Rt"] = "El cañón autopropulsado puede causar daño al mismo enemigo varias veces en la misma ronda, pero no es necesario que el jugador evite cada golpe, ya que no causa mucho daño con cada golpe.",
  ["str_guide_circle_N22_2-1_RbT"] = "Cañón autopropulsado",
  ["str_guide_circle_N22_2-1_Rb"] = "Poderosos guardias capaces de patrullar por su cuenta. Tanto el cañón principal como el del hombro son increíblemente poderosos. Solo uno de esos guardias puede causar un gran daño.",
  ["str_guide_circle_N23_1-14_LtT"] = "Astor",
  ["str_guide_circle_N23_1-14_Lt"] = "Un espíritu femenino itinerante sin dueño ni voluntad propia; todo lo que queda es una poderosa enemistad hacia los vivos. A través de siniestros rituales, este espíritu puede combinarse con Darkflow para crear una poderosa entidad sobrenatural.",
  ["str_guide_circle_N23_1-14_RtT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N23_1-14_Rt"] = "Alborota a través de un área designada y absorbe la energía de Deathly Candles para fortalecerse.",
  ["str_guide_circle_N23_1-14_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N23_1-14_Rb"] = "Apaga las velas mortales para mantener la distancia con Astor.",
  ["str_guide_circle_13-14_LtT"] = "diávola",
  ["str_guide_circle_13-14_Lt"] = "El exterior del cuerpo de la flor está fuertemente protegido por hojas duras, pero las habilidades de francotirador pueden causar daños letales a la flor y exponer su debilidad.",
  ["str_guide_circle_13-14_RtT"] = "Rasgos de Monstruo",
  ["str_guide_circle_13-14_Rt"] = "Cuando se despierta, Diavola contrarresta todos los ataques normales de los aurorianos y les inflige 1 acumulación de toxina.",
  ["str_guide_circle_13-14_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_13-14_Rb"] = "Prioriza atacar primero las flores de Diavola para paralizarlas y poder dañarlas de manera segura. Recuerda cuidar de los Dawn Sprites que convoca.",
  ["str_guide_circle_13-7-1_Lt"] = "Un Eclipsite nacido en las condiciones extremas del fin de los días. Tiene una figura distorsionada y hace tiempo que perdió la capacidad de pensar inteligentemente. Lo único que le queda son las ganas de seguir avanzando y devorando todo a su paso.",
  ["str_guide_circle_13-7-1_LtT"] = "Jormungand",
  ["str_guide_circle_13-7-1_Rt"] = "La cabeza de Jormungand es el núcleo de sus ataques. Inflige mucho daño a los enemigos cerca de su cabeza. Jormungand muere cuando a su cabeza le quedan 0 HP.",
  ["str_guide_circle_13-7-1_RtT"] = "Características de la cabeza de Jormungand",
  ["str_guide_circle_13-7-1_Rb"] = "Los jugadores deben recordar infligir daño a la cabeza de Jormungand desde la distancia. Jormungand morirá inmediatamente si su cabeza es bloqueada por obstáculos por todos lados.",
  ["str_guide_circle_13-7-1_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_13-7-2_Lt"] = "El cuerpo de Jormungand se replica a sí mismo con el tiempo y se alarga en cada ronda. Su cuerpo es inmune a todo daño.",
  ["str_guide_circle_13-7-2_LtT"] = "Características del cuerpo de Jormungand",
  ["str_guide_circle_13-7-3_Lt"] = "La cola de Jormungand es su punto débil. Todo el daño infligido a la cola se transferirá a la cabeza y harás más daño.",
  ["str_guide_circle_13-7-3_LtT"] = "Características de la cola de Jormungand",
  ["str_guide_circle_14-9-1_LtT"] = "Espíritu de linterna",
  ["str_guide_circle_14-9-1_Lt"] = "Un Eclipsite que fue modificado por Asmodeus. Sus deseos están controlados por Asmodeus, por lo que obedece todas sus órdenes.",
  ["str_guide_circle_14-9-1_RtT"] = "Características de los Monstruos I",
  ["str_guide_circle_14-9-1_Rt"] = "Si un Lantern Spirit puede teletransportarse a través de los aurorianos cuando ataca, crea una cadena que hace que tanto el daño recibido como el HP recuperado se compartan entre las partes vinculadas.",
  ["str_guide_circle_14-9-1_RbT"] = "Teletranspondose",
  ["str_guide_circle_14-9-1_Rb"] = "El espíritu de la linterna puede teletransportarse si puede atravesar la casilla en la que se encuentra el auroriano y moverse a la casilla del otro lado.",
  ["str_guide_circle_14-9-2_LtT"] = "Cadenas",
  ["str_guide_circle_14-9-2_Lt"] = "Cuando cualquiera de las partes conectadas por la cadena recibe daño o recupera HP, la otra parte recibirá la misma cantidad de daño o recuperará la misma cantidad de HP.",
  ["str_guide_circle_14-9-2_RtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_14-9-2_Rt"] = "Mantén cierta distancia de un espíritu de linterna para romper la cadena.",
  ["str_guide_circle_14-9-2_RbT"] = "¡Derrótalos o abrázalos!",
  ["str_guide_circle_14-9-2_Rb"] = "Derrotar o atraer al espíritu de la linterna hacia ti también es una forma de liberarte de la cadena que te conecta.",
  ["str_guide_circle_14-14-1_LtT"] = "asmodeo",
  ["str_guide_circle_14-14-1_Lt"] = "El poderoso Wraith tiene la aterradora habilidad de ver a través de todos los deseos de sus oponentes y disfruta manipulándolos.",
  ["str_guide_circle_14-14-1_RtT"] = "Características de los eclipses",
  ["str_guide_circle_14-14-1_Rt"] = "Asmodeus se divide en dos al entrar al campo. Un clon es inmune a las habilidades y el otro es inmune a los ataques normales. Están conectados por la Cadena de Deseo.",
  ["str_guide_circle_14-14-1_RbT"] = "cadena de deseo",
  ["str_guide_circle_14-14-1_Rb"] = "Cuando cualquiera de los Asmodeus conectados por la Cadena de Deseo recibe daño o recupera PS, el otro Asmodeus experimentará el mismo efecto. Después de que Asmodeus tome acción, se generarán Regiones Oscuras debajo de la Cadena de Deseo.",
  ["str_guide_circle_14-14-2_LtT"] = "asmodeo",
  ["str_guide_circle_14-14-2_Lt"] = "Este Asmodeus es inmune al daño de ataque normal y tiene poderosos ataques a distancia.",
  ["str_guide_circle_14-14-3_RtT"] = "asmodeo",
  ["str_guide_circle_14-14-3_Rt"] = "Esta Asmodeus es inmune al daño de habilidad y se vincula a sí misma con los Aurorianos a los que golpea con su Cadena de Pesadillas.",
  ["str_guide_circle_14-14-3_RbT"] = "cadena de pesadillas",
  ["str_guide_circle_14-14-3_Rb"] = "Los aurorianos conectados por la Cadena de Pesadillas recibirán daño por cada mosaico que atraviesen. Dejar el rango efectivo de la Cadena de Pesadillas la romperá.",
  ["str_guide_circle_14-7_LtT"] = "cerrito",
  ["str_guide_circle_14-7_Lt"] = "El nuevo Eclipsite encontrado durante la exploración parece ser una variante de un poderoso Eclipsite, excepto que está más trastornado y es mucho más destructivo.",
  ["str_guide_circle_14-7_RtT"] = "Rasgos de Monstruo",
  ["str_guide_circle_14-7_Rt"] = "Cerritus ataca a los aurorianos embistiéndolos y tiene la poderosa habilidad de invocar guijarros y cambiar el terreno. Cerritus se fortalece a medida que avanza la batalla. ¡Los ataques que no matan a Cerritus solo lo hacen más fuerte! Cada pocas rondas, Cerritus ruge enojado y entra en un estado de locura.",
  ["str_guide_circle_14-7_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_14-7_Rb"] = "Preste atención a su posición relativa de los enemigos. Usa habilidades en el momento adecuado para terminar las batallas rápidamente.",
  str_guide_circle_N24_petTry_LtT = "Orbe curativo",
  str_guide_circle_N24_petTry_Lt = "Objeto invocado de Axelia. Se cura a sí misma cuando absorbe esto con su habilidad activa o cuando el equipo lo atraviesa. Se transforma después de existir durante 2 rondas, proporciona efectos curativos adicionales.",
  str_guide_circle_N24_petTry_Lt_1 = "Objeto invocado de Axelia. Se cura a sí misma cuando absorbe esto con su habilidad activa o cuando el equipo lo atraviesa.",
  ["str_guide_circle_N25_1-4_LtT"] = "venomex",
  ["str_guide_circle_N25_1-4_Lt"] = "Se dice que es un pariente lejano de una especie de Eclipsite capaz de autodetonarse, excepto que esta variedad puede lanzar bolas de baba venenosas que causan un daño significativo a los organismos vivos.",
  ["str_guide_circle_N25_1-4_LbT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N25_1-4_Lb"] = "Rocía veneno en línea recta o en la ubicación de un auroriano, lo que inflige veneno a todos los enemigos y aliados dentro del alcance del veneno.",
  ["str_guide_circle_N25_1-4_RtT"] = "Estrategia",
  ["str_guide_circle_N25_1-4_Rt"] = "Tal vez puedas usar su veneno para hacer sufrir a otros enemigos.",
  ["str_guide_circle_N25_1-16_RtT"] = "Dreamwalker",
  ["str_guide_circle_N25_1-16_Rt"] = "Se dice que es el PhantomEl \"hermano\" de Eternal Night. Es capaz de usar diferentes tácticas según la hora del día y es extremadamente difícil de manejar.",
  ["str_guide_circle_N25_1-16_LtT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N25_1-16_Lt"] = "Tiene la capacidad de atacar a los aurorianos a distancia y puede lanzar ataques a pantalla completa. Puede invocar fantasmas que rodean a los aurorianos pero no pueden atacar.",
  ["str_guide_circle_N25_1-16_LbT"] = "Estrategia",
  ["str_guide_circle_N25_1-16_Lb"] = "Confía en un movimiento ágil para evitar que te rodeen Fantasmas.",
  ["str_guide_circle_N25_2-4_LtT"] = "Engañar",
  ["str_guide_circle_N25_2-4_Lt"] = "Posee una notable habilidad para mezclarse con su entorno. A veces, incluso parece una trampa ordinaria. Sin embargo, una vez que se revela, estalla en un alboroto asesino.",
  ["str_guide_circle_N25_2-4_LbT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N25_2-4_Lb"] = "Suele esconderse en Crud. Cuando termina la cuenta regresiva, aparece y ataca a los aurorianos.",
  ["str_guide_circle_N25_2-4_RtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N25_2-4_Rt"] = "Al restablecer los mosaicos donde se encuentra Crud, se eliminará Crud y aparecerá un Cozen.",
  ["str_guide_circle_N26_1-12_RtT"] = "Yoh",
  ["str_guide_circle_N26_1-12_Rt"] = "Una vez que el líder del pez serpiente, fue esclavizado por los aurorianos para que sirviera como herramienta de navegación. Años de creciente odio lo han convertido en un poderoso maníaco.",
  ["str_guide_circle_N26_1-12_LtT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N26_1-12_Lt"] = "Posee poderosas habilidades mágicas y puede controlar proyectiles para infligir daño a los enemigos.",
  ["str_guide_circle_N26_1-12_LbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N26_1-12_Lb"] = "Limpia \"Palabra\" y las réplicas en el campo lo antes posible para evitar daños graves.",
  ["str_guide_circle_N27_1-1_RtT"] = "Asistente afónico",
  ["str_guide_circle_N27_1-1_Rt"] = "Posible un cierto tipo de \"mentor\" de Eclipsite, ya que ambos curan a otros Eclipsites. La diferencia es que es más probable que este Eclipsite permanezca cerca de sus aliados más voluminosos para aprovechar al máximo el efecto especial de su habilidad.",
  ["str_guide_circle_N27_1-1_LtT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N27_1-1_Lt"] = "Puede restaurar el HP de otros Eclipsites. Cuantas más casillas estén ocupadas por otros Eclipsites dentro del rango de habilidad del Asistente Afónico, más fuerte será el efecto de su curación.",
  ["str_guide_circle_N27_1-1_LbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N27_1-1_Lb"] = "¡Prioriza el trato con el Asistente Afónico y evita que el Asistente Afónico sane a los otros Eclipsites!",
  ["str_guide_circle_N27_1-12_LtT"] = "Gusano de arena rosa",
  ["str_guide_circle_N27_1-12_Lt"] = "Un raro gusano de arena nativo del desierto de Rediesel. Está cubierto de escamas rosadas debido a una mutación única, lo que lo hace más poderoso y feroz que otros gusanos de arena.",
  ["str_guide_circle_N27_1-12_RtT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N27_1-12_Rt"] = "Perfora el suelo para encontrar la ubicación de su objetivo y luego sale a la luz. Escupe arena negra para atacar a los objetivos que tiene delante.",
  ["str_guide_circle_N27_1-12_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N27_1-12_Rb"] = "¡Evitar los ataques del gusano de arena rosa puede ser complicado! ¡Presta atención a tu propio estado en todo momento y termina la batalla tan pronto como puedas!",
  ["str_guide_circle_N27_2-4-1_RbT"] = "Grulla de papel",
  ["str_guide_circle_N27_2-4-1_Rb"] = "Las grullas de papel se pueden colocar en mosaicos abisales y convertir los mosaicos debajo de ellos en mosaicos cromáticos. Las grullas de papel desaparecerán después de que el equipo las atraviese.",
  ["str_guide_circle_N27_2-4-2_RbT"] = "Asistencia auroriana",
  ["str_guide_circle_N27_2-4-2_Rb"] = "Pasolo puede colocar grullas de papel en mosaicos para ayudar a su equipo a superar situaciones difíciles. ¡Recuerda usar la asistencia de habilidades de Pasolo en cada ronda!",
  str_guide_circle_N27_2_1_RtT = "Copia de seguridad Lumo",
  str_guide_circle_N27_2_1_Rt = "Los equipos de respaldo de Lumopolis se han unido a la batalla. Allied Pikers actuará después de los Eclipsites. El Constructor convocará a un Piker cuando el jugador lance la Habilidad Activa 3 veces seguidas.",
  str_guide_circle_N27_2_1_RbT = "¡Advertencia!",
  str_guide_circle_N27_2_1_Rb = "¡Protege primero al constructor aliado! Una vez que el Constructor sea derrotado, los Lumo Pikers aliados tendrán que retirarse. La DEF de todos los Aurorianos en el tablero también se verá muy debilitada.",
  str_guide_circle_N27_2_2_RbT = "Objetivo de ataque",
  str_guide_circle_N27_2_2_Rb = "Los eclipses atacarán primero nuestro Lumo Backup. Una vez que todos los equipos de Lumo Backup en el tablero sean derrotados, Eclipsites cambiará su objetivo y atacará al jugador.",
  str_guide_circle_N27_2_2_LbT = "Lucha de facciones",
  str_guide_circle_N27_2_2_Lb = "El mal de ojo del enemigo seguirá convocando a los eclipses al campo de batalla. Los jugadores deben proteger al Constructor aliado y derrotar al Brood del enemigo.",
  str_guide_circle_N28_3_4_RtT = "agujero de gusano",
  ["str_guide_circle_N28_3-4_Rt"] = "Los eclipses pueden escapar a otros lugares a través de agujeros de gusano.",
  ["str_guide_circle_N28_3-4_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N28_3-4_Rb"] = "Evita que los eclipses escapen derrotándolos o usando habilidades que los obliguen a moverse.",
  str_guide_circle_N28_1_12_LtT = "los cuatro caballeros",
  str_guide_circle_N28_1_12_Lt = "Aunque parecen miembros ordinarios del jurado, los cascos de yeso que llevan en la cabeza los hacen parecer muy sospechosos. ¡Resulta que hay eclipses escondidos debajo de ellos! Lo confuso es que parecen estar siguiendo las instrucciones de alguien...",
  str_guide_circle_N28_1_12_LbT = "Rasgos de Monstruo",
  str_guide_circle_N28_1_12_Lb = "Cada vez que 1 de los Cuatro Caballeros sea atacado o recupere HP, los otros caballeros recibirán la misma cantidad de daño o recuperarán la misma cantidad de HP.",
  str_guide_circle_N28_1_12_RbT = "Estrategia de afrontamiento",
  str_guide_circle_N28_1_12_Rb = "¡Observe cuidadosamente la posición de los Cuatro Caballeros y actúe con precaución!",
  str_guide_circle_N29_zhanqi_1_LtT = "agujero de gusano",
  str_guide_circle_N29_zhanqi_1_Lt = "Ayuda a los Eclipsites a moverse más rápido por el campo de batalla.",
  str_guide_circle_N29_zhanqi_1_LbT = "Estrategia de afrontamiento",
  str_guide_circle_N29_zhanqi_1_Lb = "Evitar el conflicto con los aurorianos y pasar por el dispositivo de teletransporte lo antes posible parece ser una opción más sensata.",
  str_guide_circle_N29_1_8_LbT = "demonio hati",
  str_guide_circle_N29_1_8_Lb = "Los recuerdos del pasado inundaron su corazón, creando al temible Demon Hound cuando el odio tomó el control.",
  str_guide_circle_N29_1_8_RbT = "Rasgos de Monstruo",
  str_guide_circle_N29_1_8_Rb = "Demon Hati consume una parte de su HP para atacar y recupera una parte de su HP perdido si se golpea a algún Aurorian. Demon Hati inflige más daño a medida que su HP disminuye.",
  str_guide_circle_N29_1_14_LbT = "demonio hati",
  str_guide_circle_N29_1_14_Lb = "Los recuerdos del pasado inundaron su corazón, creando al temible Demon Hound cuando el odio tomó el control.",
  str_guide_circle_N29_1_14_RbT = "Rasgos de Monstruo",
  str_guide_circle_N29_1_14_Rb = "Demon Hati consume una parte de su HP para atacar y recupera una parte de su HP perdido si se golpea a algún Aurorian. Demon Hati inflige más daño a medida que su HP disminuye.",
  str_guide_circle_N29_1_14_LbT_2 = "¡Cuidado!",
  str_guide_circle_N29_1_14_Lb_2 = "Cuando Demon Hati está al borde de la muerte, puede consumir energía regenerativa para recuperar su HP completo. ¡Ella también obtendrá una habilidad poderosa y mejorará sus efectos de habilidad!",
  str_guide_circle_N29_ex3_1_LbT = "demonio hati",
  str_guide_circle_N29_ex3_1_Lb = "Los recuerdos del pasado inundaron su corazón, creando al temible Demon Hound cuando el odio tomó el control.",
  str_guide_circle_N29_ex3_1_RbT = "Rasgos de Monstruo",
  str_guide_circle_N29_ex3_1_Rb = "Demon Hati consume una parte de su HP para atacar y recupera una parte de su HP perdido si se golpea a algún Aurorian. Demon Hati inflige más daño a medida que su HP disminuye.",
  str_guide_circle_N29_ex3_1_LbT_2 = "¡Cuidado!",
  str_guide_circle_N29_ex3_1_Lb_2 = "Cuando Demon Hati está al borde de la muerte, puede consumir energía regenerativa para recuperar su HP completo. ¡Ella también obtendrá una habilidad poderosa y mejorará sus efectos de habilidad!",
  str_guide_circle_N29_ex3_1_RbT_2 = "¡Advertencia!",
  str_guide_circle_N29_ex3_1_Rb_2 = "Demon Hati contrarresta las habilidades activas si los aurorianos las lanzan contra ella.",
  str_guide_warn_11900702 = "Este es el nivel de refinamiento del equipo actual. Cada equipo se puede refinar 3 veces.",
  str_guide_warn_11900703 = "Los efectos de refinamiento del equipo se muestran aquí. Además de mejorar los atributos básicos, el refinamiento también puede mejorar las habilidades de Aurorian.",
  str_guide_warn_11900704 = "Además de cumplir con los requisitos básicos de desbloqueo para el refinamiento, los aurorianos también necesitan consumir los materiales correspondientes.",
  str_guide_warn_11900802 = "Este es el nivel de refinamiento del equipo actual. Cada equipo se puede refinar 3 veces.",
  str_guide_warn_11900803 = "Los efectos de refinamiento del equipo se muestran aquí. Además de mejorar los atributos básicos, el refinamiento también puede mejorar las habilidades de Aurorian.",
  str_guide_warn_11900804 = "Además de cumplir con los requisitos básicos de desbloqueo para el refinamiento, los aurorianos también necesitan consumir los materiales correspondientes.",
  str_guide_warn_11900805 = "El paradigma se puede obtener a través de premios de actividad semanales, entre otros métodos. Toque el icono para ver la lista detallada de fuentes de Paradigm.",
  ["str_guide_circle_N30_15-2_RtT"] = "Soldados Illumina",
  ["str_guide_circle_N30_15-2_Rt"] = "Soldados de combate comunes en el ejército de Illumina, conocidos por su habilidad con rifles y cuchillos de combate, así como por su tenacidad, ética de trabajo, proactividad en la batalla y espíritu de lucha intrépido.",
  ["str_guide_circle_N30_15-2_LbT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N30_15-2_Lb"] = "Usa más ataques a distancia. Cuando la batalla se intensifica, acércate rápidamente a los enemigos y enfréntalos en combate cuerpo a cuerpo para acabar con ellos lo antes posible.",
  ["str_guide_circle_N30_15-2_RbT"] = "¡Cuidado!",
  ["str_guide_circle_N30_15-2_Rb"] = "Cuando HP es inferior al 50%, todos los ataques con armas se convertirán en ataques cuerpo a cuerpo con un cuchillo de combate. Al mismo tiempo, todos los moretones acumulados se convertirán en HP restaurado y aumentarán ATK y DEF.",
  ["str_guide_circle_N30_15-9_Lt"] = "Un robot de combate desarrollado por Illumina. Se ha desempeñado extremadamente bien en las pruebas internas, pero aún no se ha probado en combate real.",
  ["str_guide_circle_N30_15-9_LtT"] = "Taladrador",
  ["str_guide_circle_N30_15-9_Lb"] = "Driller tiene 2 estados. Se mueve por el campo en su estado normal y cava una cierta cantidad de campos de energía y campos de apoyo en cada ronda. Cuando hay una cierta cantidad de campos de energía en el campo, absorbe y ensambla una plataforma de perforación.",
  ["str_guide_circle_N30_15-9_LbT"] = "Características del enemigo",
  ["str_guide_circle_N30_15-9_Rb"] = "Cuando hay menos campos de soporte en el campo, el perforador excava más campos de soporte.",
  ["str_guide_circle_N30_15-9_RbT"] = "Nota",
  ["str_guide_circle_N30_15-9-2_Lt"] = "Los campos de energía son mosaicos completamente energizados que se pueden usar para ensamblar la plataforma de perforación. Detiene el paso de unidades en tierra cuando está presente.",
  ["str_guide_circle_N30_15-9-2_LtT"] = "campo de energía",
  ["str_guide_circle_N30_15-9-2_Rb"] = "Si hay 6 campos de energía en el campo de batalla cuando Driller entra en acción, Driller activa una habilidad especial y construye una plataforma de perforación.",
  ["str_guide_circle_N30_15-9-2_RbT"] = "Piezas necesarias para el montaje.",
  ["str_guide_circle_N30_16-14_Lt"] = "Como uno de los Espectros más poderosos, ataca con todas sus fuerzas cuando su estatus se ve amenazado.",
  ["str_guide_circle_N30_16-14_LtT"] = "Figerald",
  ["str_guide_circle_N30_16-14_Lb"] = "Los mosaicos colapsan después de que los aurorianos se mueven a través de ellos. Cuando no hay suficientes fichas en el campo de batalla, Figerald libera su poder para remodelar el espacio e inflige daño.",
  ["str_guide_circle_N30_16-14_LbT"] = "Características del enemigo",
  ["str_guide_circle_N30_16-14_Rt"] = "Planifica bien tu ruta para minimizar la cantidad de veces que recibes daño cuando Figerald remodela el espacio.",
  ["str_guide_circle_N30_16-14_RtT"] = "Estrategia de afrontamiento",
  str_guide_circle_N30_tower10_LtT = "Cazador mecánico",
  str_guide_circle_N30_tower10_LbT = "Características del enemigo",
  str_guide_circle_N30_tower10_RbT = "¡Advertencia!",
  str_guide_circle_N30_tower10_Lt = "Un antiguo guardián creado con el único propósito de proteger los secretos de esta tierra. Es difícil escapar de sus ataques, y también tiene una autorrecuperación increíble para seguir funcionando a lo largo de los siglos. Nadie querrá afrontarlo solo.",
  str_guide_circle_N30_tower10_Lb = "Crea una zona protegida dentro de 2 grupos circundantes de sí mismo cada ronda. Los aurorianos dentro de la zona protegida recibirán daño adicional cada vez que ataquen o se muevan. Si Mechanical Huntsman es invencible cuando entra en acción, consumirá su energía regenerativa para recuperar su HP completo.",
  str_guide_circle_N30_tower10_Rb = "Cuando Mechanical Huntsman entra en el estado invencible, desata un ataque extremadamente peligroso que reduce a todos los enemigos en la zona protegida a 1 HP en la siguiente ronda.",
  str_guide_circle_N30_tower10_3_LtT = "bennuguardian",
  str_guide_circle_N30_tower10_3_Lt = "Un antiguo guardián que reside en las profundidades del Territorio Secreto, despertado debido a los frecuentes disturbios de los intrusos. Incluso los Eclipsites tienen miedo de sus poderosas habilidades. Deambula por el campo de batalla sin rumbo fijo.",
  str_guide_circle_N30_tower10_3_LbT = "Características del enemigo",
  str_guide_circle_N30_tower10_3_Lb = "Posee un gran poder. Acumula Furia cuando es atacado. Cuando Fury alcanza cierto nivel, entra en un estado Enfurecido, lo que reduce el daño recibido y lanza poderosas habilidades adicionales. Si Bennuguardian es invencible cuando entra en acción, consumirá su energía regenerativa para recuperar su HP completo.",
  str_guide_circle_N30_tower10_3_RbT = "¡Advertencia!",
  str_guide_circle_N30_tower10_3_Rb = "¡Supervisa la furia de Bennuguardian en todo momento y actúa con cautela!",
  ["str_guide_circle_15-14_LtT"] = "Estado de prueba Helios",
  ["str_guide_circle_15-14_Lt"] = "Después de vivir solo durante más de una década en la Zona Oscura, este soldado de Illumina se ha olvidado de todo menos de luchar. Lo aterrador es que se ha vuelto más fuerte en la batalla después de haber sido modificado por alguien...",
  ["str_guide_circle_15-14_RtT"] = "Características del enemigo",
  ["str_guide_circle_15-14_Rt"] = "Una entidad que tiene fuertes habilidades de combate y acumula Contusiones al recibir daño. Cuando sus ataques fallan en su objetivo, se libera una marca de terror en el campo. Las habilidades de Helios se vuelven más poderosas con cada marca de terror en el campo.",
  ["str_guide_circle_15-14_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_15-14_Rb"] = "¡Toma nota de dónde están las marcas para evitar los ataques de Helios!",
  str_guide_circle_621_RtT = "Azulejo de prisma en forma de cruz",
  str_guide_circle_621_Rt = "Cuando se conecta con otras fichas, las 4 fichas a su alrededor en forma de cruz se convierten al mismo color.",
  ["str_guide_circle_N30_16-9_Lt"] = "Este eclipse especial se parece a las arañas y ha aprendido el comportamiento de los grupos de arañas durante su camino evolutivo. Se esconde en la oscuridad donde la luz del sol no puede llegar.",
  ["str_guide_circle_N30_16-9_LtT"] = "reina araña",
  ["str_guide_circle_N30_16-9_Lb"] = "Al poseer fuertes habilidades reproductivas, teje telas de araña en un entorno de caza.",
  ["str_guide_circle_N30_16-9_LbT"] = "Rasgos de Monstruo",
  ["str_guide_circle_N30_16-9_Rt"] = "Concentre su atención en despejar las telarañas y elimine los huevos de araña y las crías de araña invocados por la Reina Araña lo más rápido que pueda.",
  ["str_guide_circle_N30_16-9_RtT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_N30_16-3_Lt"] = "Un destacado miembro de Illumina y discreto experto en combate cuerpo a cuerpo con la capacidad de detectar y reaccionar ante los movimientos del enemigo durante intensas batallas, lo que permite contraataques efectivos.",
  ["str_guide_circle_N30_16-3_LtT"] = "Soldado de élite Illumina",
  ["str_guide_circle_N30_16-3_Lb"] = "Cada vez que el enemigo usa una habilidad activa, avanza instantáneamente 1 ficha hacia el enemigo y ataca.",
  ["str_guide_circle_N30_16-3_LbT"] = "Habilidad de contador",
  ["str_guide_circle_N30_16-3_Rt"] = "Acumula moretones al recibir daño. Si el jugador no inflige daño a esta unidad durante esta ronda, inmediatamente cura todos los moretones para restaurar HP.",
  ["str_guide_circle_N30_16-3_RtT"] = "Mejora tenaz",
  str_guide_warn_12000101 = "¡El evento Descenso de la Iluminación ya está en marcha! ¡Durante el período del evento, el Centro de Suministros de Illumina estará abierto para todos los Navegantes!",
  str_guide_warn_12000102 = "Los pases de suministros obtenidos al gastar Prism se pueden canjear por varias recompensas en el Centro de suministros de Illumina.",
  str_guide_warn_12000103 = "¡Ingrese al nuevo simulador de ejercicios militares Team Battle de Gronru para participar en un entrenamiento integral con sus Aurorianos!",
  str_guide_warn_12000104 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_12000105 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_12000106 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_12100101 = "¡Viaje al Pasado ya ha comenzado! Reviviremos los viejos tiempos con Mia en el Día de la Familia y descubre la verdad detrás de lo que sucedió.",
  str_guide_warn_12100102 = "En Bottomless Chasm, nos enfrentaremos a una serie de difíciles desafíos.",
  str_guide_warn_12100103 = "Las gotitas de cristal obtenidas al completar etapas del evento y gastar prismas se pueden usar para canjear varias recompensas de la sala de adivinación.",
  str_guide_warn_12100104 = "Recuerda iniciar sesión en el juego todos los días para obtener las recompensas de On Memories of Old.",
  str_guide_warn_12100105 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_12100106 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  ["str_guide_circle_N31_1-14_Lt"] = "Mime Kartima blande su escudo, reduciendo el daño de los ataques frontales. Pierde efecto cuando está aturdido, asustado, paralizado o infligido con otros efectos de control.",
  ["str_guide_circle_N31_1-14_LtT"] = "Kartima: Guarda escudo",
  ["str_guide_circle_N31_1-14_Lb"] = "Mime Kartima es inmune a los efectos de control durante 2 rondas después de unirse a la batalla.",
  ["str_guide_circle_N31_1-14_LbT"] = "Kartima: Inflexible",
  ["str_guide_circle_N31_1-14_Rt"] = "Mime Kartima usa el martillo de cadena para atacar un área en frente a su derecha o usa el escudo para derribar al objetivo en frente a la izquierda",
  ["str_guide_circle_N31_1-14_RtT"] = "Técnica de batalla",
  ["str_guide_circle_N31_1-16_Lt"] = "Tiene un control inmenso sobre su entorno y es parcialmente resistente a los ataques y habilidades normales debido al efecto del Phantom Crystal.",
  ["str_guide_circle_N31_1-16_LtT"] = "Joshua: alma contaminada",
  ["str_guide_circle_N31_1-16_Lb"] = "Elija diferentes estrategias de acción, como si usar ataques normales o habilidades contra Joshua: Tainted Soul en la ronda actual según el efecto del Phantom Crystal.",
  ["str_guide_circle_N31_1-16_LbT"] = "Técnica de batalla",
  str_guide_popstar_fail_tip = "Estrategia de eliminación",
  str_guide_popstar_fail_desc = "Usa las habilidades de Aurorian para eliminar tantas fichas como sea posible en cada paso. Al quitar los mosaicos, pensar detenidamente en la condición en que estarán los mosaicos durante el siguiente paso hará que las cosas sean infinitamente más fáciles para usted.",
  str_guide_circle_N31_star1_Rt = "Se puede quitar junto con los azulejos. Si no se elimina, se convierte en un mosaico roto después de que finaliza la cuenta regresiva.",
  str_guide_circle_N31_star1_RtT = "Azulejo de runa",
  str_guide_circle_N31_star2_Rt = "Al eliminar mosaicos mejorados, este mosaico se trata como un mosaico eliminado adicionalmente.",
  str_guide_circle_N31_star2_RtT = "Casilla mejorada",
  str_guide_circle_N31_star3_Rt = "Los mosaicos bloqueados no pueden convertir su color. Después de eliminar las fichas bloqueadas, se convierten en fichas normales.",
  str_guide_circle_N31_star3_RtT = "Casilla Bloqueada",
  str_guide_warn_6012102 = "Toca aquí para ver los detalles del rango.",
  str_guide_warn_6012104 = "Toque aquí para ver la Clasificación.",
  str_guide_warn_6012106 = "Toque aquí para continuar viendo.",
  str_guide_warn_6012107 = "Puedes obtener Expresiones olvidadas y Susurros olvidados completando Cazarrecompensas.",
  str_guide_warn_6012108 = "Los navegantes pueden intercambiar Expresiones olvidadas y Susurros olvidados en el Puerto exiliado por Solamber, Aurorians y Star Flares.",
  str_guide_warn_6012202 = "Podemos configurar varios equipos para desafiar a los jefes. El daño total de todos nuestros equipos se registrará como resultado final.",
  str_guide_warn_6012203 = "No habrá clasificaciones ni emblemas disponibles si no has comenzado tu desafío.",
  str_guide_warn_6012204 = "Toca aquí para ver los detalles del rango.",
  str_guide_warn_6012206 = "Toque aquí para ver su clasificación actual.",
  str_guide_warn_6012208 = "Toque aquí para continuar viendo.",
  str_guide_warn_6012209 = "Puedes obtener Expresiones olvidadas y Susurros olvidados completando Cazarrecompensas.",
  str_guide_warn_6012210 = "Los navegantes pueden intercambiar Expresiones olvidadas y Susurros olvidados en el Puerto exiliado por Solamber, Aurorians y Star Flares.",
  str_guide_warn_12200201 = "¿Eh? ¿Dónde estoy? ¿Es ese un... otro Cristal de la Memoria Eterna?",
  str_guide_warn_12200202 = "¿No logramos salir al final...? ¡Está bien! ¡Recita el hechizo del viaje en el tiempo en voz alta y toca aquí!",
  str_guide_warn_12200301 = "Cállate... Alguien parece estar hablando cerca. ¡Ejem, no estoy escuchando a escondidas! Esto se llama... ¡recopilación de información!",
  str_guide_warn_12200401 = "¿Ver? Sabía que tenía razón. ¡Tenemos en nuestras manos información increíble! ¿Qué? ¿No puedes recordar todo? ¡Entonces pon la información que reunimos aquí!",
  str_guide_warn_12200402 = "Mira, toda la información está aquí, ¡ahora no tienes que preocuparte por olvidar cosas! Presta atención a todo lo que te rodea y llena todo este espacio.",
  str_guide_warn_12200101 = "¡El borde del colapso ha comenzado! ¡En The Divergence, investigaremos el misterio del Cristal de la Memoria Eterna!",
  str_guide_warn_12200102 = "Nos enfrentaremos a una serie de difíciles desafíos en el mundo de Shattered Illusion.",
  str_guide_warn_12200103 = "Las Lágrimas de cristal obtenidas al completar etapas del evento y gastar Prisma se pueden intercambiar por varias recompensas en el Salón del Recuerdo.",
  str_guide_warn_12200104 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas de Wistful Musing.",
  str_guide_warn_12200105 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_12200106 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_circle_N33_15_Lt = "Una mariposa extremadamente rara, se rumorea que solo aparece cerca del Valle de Denuo. Es de naturaleza reclusiva, con sentidos muy agudos. No se debe subestimar el poder de combate de las Denuo Diosas adultas.",
  str_guide_circle_N33_15_LtT = "Diosa Denuo",
  str_guide_circle_N33_15_Lb = "Catalizan el crecimiento de las plantas mediante la polinización, protegiéndose a sí mismos mientras infligen un gran daño a los enemigos.",
  str_guide_circle_N33_15_LbT = "Características del enemigo",
  str_guide_circle_N33_15_Rt = "Elige tu camino sabiamente para evitar que la Diosa Denuo polinice la Hierba Encantada Sadesiana, haciéndola más agresiva.",
  str_guide_circle_N33_15_RtT = "Estrategia de afrontamiento",
  str_guide_circle_chapter18_14_Rb = "Realiza ataques intensivos para paralizar al Engine VII Corrupto, retrasando su asalto a la puerta del Bastión de Illumina.",
  str_guide_circle_chapter18_14_RbT = "Estrategia de afrontamiento",
  str_guide_circle_chapter18_14_Rt = "Originalmente un mecha de combate colosal creado por Illumina, se convirtió en una de las amenazas más formidables después de que su piloto perdiera la razón debido a la contaminación por el lodo.",
  str_guide_circle_chapter18_14_RtT = "Dañado Engine VII",
  str_guide_warn_80010102 = "Solo tú puedes entrar en los sueños de Eve...",
  str_guide_warn_80010103 = "Completa las misiones detalladas en los Fragmentos de memoria para ganar Lumamber y descubre historias ocultas sobre Eve.",
  str_guide_warn_80010104 = "Las Metamorpha y los Fragmentos de Sedimento adquiridos en el Sueño se pueden cambiar aquí por una variedad de recompensas, incluido el atuendo de Eve.",
  str_guide_warn_80010105 = "Las pequeñas baratijas recolectadas en el Sueño son guardadas cuidadosamente aquí por Eve.",
  str_guide_warn_80010106 = "Completa misiones en el Sueño para adquirir el Stand By Me Set.",
  str_guide_warn_80010107 = "Toque aquí para ver los detalles.",
  str_guide_warn_80010202 = "Esto... parece ser una copa que me dio alguien especial.",
  str_guide_warn_80010203 = "¡Recuerdo que esta copa puede otorgarme poderes especiales!",
  str_guide_warn_80010204 = "¿Eh? La taza está vacía... ¡Necesito recolectar Ondas de Alegría para llenarla! Cuantas más recoja, más poder podré obtener.",
  str_guide_warn_80010205 = "Pero espera... ¿hay alguien en la puerta?",
  str_guide_circle_80010206 = "¡¿Q-Qué es eso?!",
  str_guide_circle_80010207 = "No hay problema... ¡No tengo miedo! ¡Toca aquí, quiero ir y averiguarlo!",
  str_guide_warn_80010208 = "Me pregunto quién es... ¿Vienen por mí?",
  str_guide_circle_80010304 = "¡Oh! Lo encontré, ¿es esa... la misma sombra de antes?",
  str_guide_warn_80010305 = "¿Esa sombra puede invocar eclipses? Ahora no puedo simplemente ignorarlo, ¿verdad?",
  str_guide_warn_80010306 = "Mi profesor me dijo que si el enemigo es demasiado fuerte, no te involucres demasiado en la pelea. ¡Puedes intentar cambiar el nivel de dificultad!",
  str_guide_warn_80010307 = "Pesadilla es más desafiante que Reverie, pero si puedo superar Pesadilla con 3 estrellas, podría obtener Ripples of Joy y mejorar Smiles Lead to Happiness.",
  str_guide_warn_80010308 = "Cada vez que me enfrente a Omen, mi ingenio se verá afectado...",
  str_guide_warn_80010309 = "¡Pero no te preocupes! Hago ejercicio diligentemente para mantenerme en forma, así que a las 05:00 todos los días, ¡el punto Wit se recuperará en 3 puntos! Pero una vez que alcanza el límite máximo, no se puede aumentar más...",
  str_guide_circle_80010402 = "¡Lo encontré!",
  str_guide_warn_80010403 = "De todos modos, dejémoslo de lado por ahora.",
  str_guide_warn_80010404 = "Después de recolectar tantas cosas, ¿habrá alguna reacción mágica entre ellos?",
  str_guide_warn_80010405 = "Ah... casi lo olvido, ¡todavía tengo que ir tras esa sombra!",
  str_guide_warn_80010406 = "¡Desliza la pantalla para observar bien el entorno!",
  str_guide_warn_80010407 = "Toque aquí para volver a la vista original.",
  str_guide_warn_80010408 = "Hay mucho que hacer, por lo que es mejor mantener la información aquí por ahora.",
  str_guide_circle_80010501 = "Los adultos nunca me dejan ir más allá de esta puerta... ¿así que la única forma es romperla si quiero salir?",
  str_guide_circle_80010502 = "Lo averiguaremos.",
  str_guide_circle_80011101 = "¿Q-Qué es eso?! ¿Están tratando de causar estragos en este mundo... Humph, ¡no es como si me asustara! Toca aquí, y los ahuyentaré en persona!",
  str_guide_warn_80010601 = "¿Me he vuelto más fuerte? Las próximas batallas deberían ser un poco más fáciles ahora.",
  str_guide_warn_80010701 = "¿He adquirido una habilidad completamente nueva? ¡Lo intentaré en un rato!",
  str_guide_warn_80010121 = "¿Eh? ¿Qué es esto?",
  str_guide_warn_80010122 = "¡Vaya, parece que he dominado un poder único? Jeje, ¡vamos a probarlo! Parece que se puede usar una vez cada dos rondas.",
  str_guide_warn_80010521 = "Eh, ¿mi poder ha cambiado?",
  str_guide_warn_80010522 = "¿Elegir un área? Eso no parece difícil. ¡Te tengo cubierto!",
  str_guide_warn_80010931 = "¿Dominaste un nuevo poder?",
  str_guide_warn_80010932 = "Muy bien, ¡hagámoslo!",
  str_guide_warn_80011331 = "Mi poder ha cambiado de nuevo...",
  str_guide_warn_80011332 = "Parece que ahora puedo desatar este poder sin descanso...",
  str_guide_warn_80011631 = "¡Dominé otro poder más!",
  str_guide_warn_80011632 = "¡Con este poder, no dudaré más!",
  str_guide_warn_12300101 = "Parece que estás contento con el resort. ¿Puedo hablar contigo en privado entonces?",
  str_guide_warn_12300201 = "Las instalaciones han producido nuevas Monedas de Pase de nuevo. Tú necesitas recolectarlas y usarlas para formar un círculo virtuoso.",
  str_guide_warn_12300202 = "Las monedas de pase del Distrito Hotelero están listas para su colección. Es trabajo del asistente averiguar cómo usarlas de manera eficiente.",
  str_guide_warn_12300203 = "¿Me preguntas cómo se usan las Monedas Pass? Simplemente úsalas para mejorar las instalaciones directamente. Las instalaciones mejoradas también producirán Monedas Pass a una velocidad mayor. Así es como los negocios usan el dinero para ganar más dinero.",
  str_guide_warn_12300204 = "¿Quieres saber por qué no puedes recolectar todas las Monedas de Pase de una vez? Esto se debe a consideraciones de seguridad. ¡Lo principal es que se siente más seguro recogerlas una por una y sostenerlas!",
  str_guide_warn_12300205 = "¿Todavía recuerdas cómo mejorar las instalaciones? ¡Vamos a intentarlo ahora!",
  str_guide_warn_12300301 = "Para mejorar una instalación, necesitas Monedas de Pase y cumplir ciertas condiciones. Déjame ver... ¡Sí! Esta se puede mejorar ahora.",
  str_guide_warn_12300302 = "Las instalaciones mejoradas serán más populares y podrán producir Pass Coins de manera más eficiente. Al actualizar las instalaciones, también se desbloquearán aventuras con otros Aurorians y se mejorarán las recompensas.",
  str_guide_warn_12300303 = "Toca aquí para firmar el plan de mejora y completar la actualización.",
  str_guide_warn_12300401 = "¡Se ha actualizado ahora! También he recogido las Monedas de Pase que olvidaste recoger antes para ti. ¡De nada!",
  str_guide_warn_12300501 = "Creo que has desbloqueado aventuras con otros Aurorians. Vamos a verlo.",
  str_guide_warn_12300601 = "Parece que una chica hermosa, inteligente, gentil y agradable te está esperando.",
  str_guide_warn_12300701 = "En cuanto a cómo desbloquear aventuras con Aurorians... No creo que necesite enseñarte eso, ¿cierto?",
  str_guide_warn_12300801 = "Puedes ver aventuras desbloqueadas y revisar las aventuras que ya has vivido en la Guía de Aventuras.",
  str_guide_warn_12300802 = "Si tienes alguna pregunta sobre el funcionamiento del complejo, puedes consultar el manual que preparé especialmente para ti.",
  str_guide_warn_12400101 = "¡El evento Valley Oasis ha comenzado! Durante las atracciones diurnas, exploraremos varias instalaciones dentro del país de las maravillas.",
  str_guide_warn_12400102 = "Durante las Fiestas Nocturnas, nos enfrentaremos a desafíos más difíciles en el parque de diversiones al amparo de la oscuridad.",
  str_guide_warn_12400103 = "En Park Tycoon seremos los encargados de gestionar el parque de atracciones. ¡Asegúrate de cuidarlo bien!",
  str_guide_warn_12400104 = "Los tokens de Claw Machine obtenidos al completar las etapas del evento y gastar Prism se pueden usar para canjear varias recompensas de Claw Machines.",
  str_guide_warn_12400105 = "Recuerde iniciar sesión en el juego todos los días para obtener recompensas en el contador de inicio de sesión de invitados.",
  str_guide_warn_12400106 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_12400107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_12500101 = "Una sinfonía de crepúsculo ya está disponible. ¡Completemos la misión de tus amigos de Illumina en el juego Twilight Tactics y reconstruyamos la ciudad!",
  str_guide_warn_12500102 = "En el juego On the Cusp of Gloom, enviaremos un equipo de avanzada a la investigación cerca de la zona del crepúsculo para descubrir el plan de los Eclipsites.",
  str_guide_warn_12500103 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por iniciar sesión en New Forces.",
  str_guide_warn_12500104 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_12500105 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_10181401 = "Aquí se muestra la durabilidad de la Puerta de la Fortaleza. Lanza tus cohetes cuando el motor corrupto VII avance cerca de la puerta.",
  str_guide_circle_80010521_Lb = "Este es el que sostiene la muñeca. Cuando es derrotado, inflige daño a todos los Eclipsites en el campo y pasa al muñeco al azar. Cuando otros Eclipsites son derrotados primero, el poseedor de la muñeca gana un escudo de conteo.",
  str_guide_circle_80010521_LbT = "Causa lúdica",
  str_guide_circle_80010521_Rb = "¡Desentraña ilusiones con la muñeca!",
  str_guide_circle_80010521_RbT = "Muñeca Desgastada",
  str_guide_circle_80010621_Lt = "Al comienzo de la batalla, Forest Evil Eyes estará dormido durante 3 rondas, y otros Evil Eyes enfrentarán una disminución sustancial en DEF durante este tiempo. Al ser atacado, el mal de ojo se despertará.",
  str_guide_circle_80010621_LtT = "Diligente",
  str_guide_circle_80010621_Lb = "Antes de irnos, déjame tomar un descanso...",
  str_guide_circle_80010621_LbT = "Muñeca Desgastada",
  str_guide_circle_80010721_Lt = "Si los escudos de conteo no están todos rotos al final de la ronda, este enemigo inflige daño fijo al jugador una vez.",
  str_guide_circle_80010721_LtT = "Ira narcisista",
  str_guide_circle_80010721_Rt = "¿Es esta... la única forma de llamar tu atención?",
  str_guide_circle_80010721_RtT = "Muñeca Desgastada",
  str_guide_circle_80010821_Lt = "El jefe acumula energía cada 3 rondas. Cada acumulación de energía otorga un bono de ATK del 3%. Si todas las acumulaciones no se eliminan al final de la ronda, el jefe adquirirá 8 acumulaciones de escudo de conteo.",
  str_guide_circle_80010821_LtT = "Agarre de hierro",
  str_guide_circle_80010821_Rt = "Atraviesa... la jaula... solo para... despertarte...",
  str_guide_circle_80010821_RtT = "Muñeca Desgastada",
  str_guide_circle_80010821_Rb = "Cada vez que el jefe sea atacado, se eliminará 1 pila de la marca. Estas marcas de energía mejoran significativamente el ATK y la capacidad de supervivencia del jefe, ¡así que es crucial lidiar con ellas lo más rápido posible!",
  str_guide_circle_80010821_RbT = "Estrategia de afrontamiento",
  str_guide_circle_80011021_Rt = "Todos los enemigos obtienen un impulso significativo en ATK. Los aurorianos pueden restaurar su HP infligiendo daño constantemente a los enemigos.",
  str_guide_circle_80011021_RtT = "Contraataque mortal",
  str_guide_circle_80011021_Rb = "¿Cuál es la diferencia entre parar y rendirse?",
  str_guide_circle_80011021_RbT = "\"Eve\"",
  str_guide_circle_80011121_Rt = "El equipo puede usar el Conveyor Vortex para teletransportarse a cualquier parte del campo y lanzar Chain Combos. Aumenta el daño del combo en cadena.",
  str_guide_circle_80011121_RtT = "Combo Gratis",
  str_guide_circle_80011121_Rb = "Ven conmigo. Puedes ir a donde quieras.",
  str_guide_circle_80011121_RbT = "\"Eve\"",
  str_guide_circle_80011421_Rt = "La generación de runas es ineficiente, y Shadow ahora invocará directamente a Shadowgeists.",
  str_guide_circle_80011421_RtT = "Características del enemigo",
  str_guide_circle_80011421_Rb = "Al conectar mosaicos, el daño infligido por los aurorianos aumentará considerablemente, incluidos los ataques normales y los efectos de daño adicionales.",
  str_guide_circle_80011421_RbT = "Características del equipo",
  str_guide_circle_80011521_Rt = "Derrota a Enferno para despejar el escenario. Spellhound seguirá reapareciendo antes de que Enferno sea derrotado.",
  str_guide_circle_80011521_RtT = "Características del enemigo",
  str_guide_circle_80010921_Lb = "Todos los Eclipsites presentes pueden reaparecer una vez. Cuando un Eclipsite muere, todos los Eclipsites restantes en el campo reciben un aumento en ATK.",
  str_guide_circle_80010921_LbT = "Características del enemigo",
  str_guide_circle_80010921_Rb = "Cuanto más luchas, más duele.",
  str_guide_circle_80010921_RbT = "\"Eve\"",
  str_guide_circle_80011321_Lb = "El número de acumulaciones de Marca de Penetrabilidad aumentará significativamente con las habilidades enemigas, pero cada ataque del jugador reducirá la Marca de Penetrabilidad en una acumulación.",
  str_guide_circle_80011321_LbT = "Características del enemigo",
  str_guide_circle_80011321_Rb = "El efecto negativo de las Marcas de penetración aumenta considerablemente. ¡Asegúrate de reducir el número de marcas de penetración atacando al enemigo lo más rápido posible!",
  str_guide_circle_80011321_RbT = "Estrategia de afrontamiento",
  str_guide_circle_80011621_Lb = "A partir de esta etapa, el equipo gana entradas especiales. ¡Cada vez que el enemigo recibe daño antes de que el equipo conecte las fichas, el ataque de todos los aurorianos del equipo aumenta en un 1 % durante esa ronda!",
  str_guide_circle_80011621_LbT = "El último crecimiento",
  ["str_guide_circle_CN2-18_Lt"] = "El dolor del aislamiento y el miedo a ser cortado, esos recuerdos insoportables del pasado, han moldeado a la persona conocida como Eve hoy.",
  ["str_guide_circle_CN2-18_LtT"] = "duelo Eve",
  ["str_guide_circle_CN2-18_Rt"] = "Al comienzo de cada ronda, convoca a un Dawn Flor en una ubicación determinada para restaurar HP; cada Dawn Flower otorga un impulso de recuperación adicional.",
  ["str_guide_circle_CN2-18_RtT"] = "Características del enemigo",
  ["str_guide_circle_CN2-18_Rb"] = "En rondas específicas, Eve recibirá una gran cantidad de acumulaciones de inmunidad. Es esencial reducir estas acumulaciones tanto como sea posible a través de daños de alta frecuencia; de lo contrario, en la siguiente ronda, se restaurará una cantidad considerable de HP según el número restante de acumulaciones.",
  ["str_guide_circle_CN2-18_RbT"] = "Descripción de la habilidad",
  str_guide_circle_N34_18_1_RtT = "Médico de Illumina",
  str_guide_circle_N34_18_1_Rt = "Dondequiera que esté el Médico Illumina, la moral se eleva, porque los compañeros saben que sus heridas no quedarán sin tratamiento. La Federación Illumina, consciente de este hecho, proporciona a estos médicos una protección mejorada, aumentando significativamente sus capacidades de supervivencia.",
  str_guide_circle_N34_18_1_LbT = "Rasgos de Monstruo",
  str_guide_circle_N34_18_1_Lb = "Un Soldado Illumina sin capacidades de combate. Restaura HP para un Soldado Illumina cercano y restaura una cierta parte de su propio Moretón.",
  str_guide_circle_N34_18_1_RbT = "¡Cuidado!",
  str_guide_circle_N34__18_1_Rb = "Al recibir daño, el Médico Illumina acumula Contusiones equivalentes al 50% del daño recibido. Además, su DEF aumenta a medida que su HP disminuye.",
  str_guide_circle_N34_18_2_RtT = "Señalero Illumina",
  str_guide_circle_N34_18_2_Rt = "Equipado con un comunicador compacto, el Comunicador Illumina lleva una carga pesada. Por lo tanto, la Federación Illumina ha diseñado un aparato de soporte especializado, facilitando su transmisión de señales en movimiento, lo cual es el origen del nombre de esta unidad.",
  str_guide_circle_N34_18_2_LbT = "Rasgos de Monstruo",
  str_guide_circle_N34_18_2_Lb = "Un Soldado Illumina sin capacidades de combate pero capaz de invocar refuerzos Illumina en el campo de batalla.",
  str_guide_circle_10170901_RtT = "Tejedor del Terror",
  str_guide_circle_10170901_Rt = "Impulsado por una obsesión de aniquilar a todos, ignora el agotamiento de su propia energía, persiguiendo incansablemente el objetivo, incluso si eso significa avanzar gradualmente hacia su propia destrucción.",
  str_guide_circle_10170901_LbT = "Detalles pasivos",
  str_guide_circle_10170901_Lb = "Cada vez que el movimiento del equipo termine, Dreadweaver hará que el equipo cambie de posición inmediatamente, afectando el lanzamiento de Combos en Cadena.",
  str_guide_circle_10170901_RbT = "Características de Ataque",
  str_guide_circle_10170901_Rb = "Cuando el HP de Dreadweaver caiga por debajo del 50%, iniciará un ritual de sacrificio. En la siguiente ronda, quemará casi todo su HP, infligiendo un enorme daño verdadero a los jugadores. Este efecto solo puede activarse una vez.",
  str_guide_circle_2002901_RtT = "Tanque Illumina L5",
  str_guide_circle_2002901_Rt = "Fabricado a través de modificaciones de camiones, el Tanque Illumina L5 cuenta con una armadura ligera, lo que lo hace perfecto para la fabricación en masa. Su capacidad de carga y sus cañones de disparo rápido acaban rápidamente con las unidades ligeras enemigas.",
  str_guide_circle_2002901_LbT = "Características del enemigo",
  str_guide_circle_2002901_Lb = "Basándose en las posiciones enemigas, opta por disparar una ráfaga rápida de tiros o una embestida cargada para atacar.",
  str_guide_circle_2003001_RtT = "Lanzallamas Illumina",
  str_guide_circle_2003001_Rt = "\"Reducir a todos los adversarios a cenizas\": esto ejemplifica la eficiencia y la crueldad de las fuerzas de Illumina. Ante las llamas furiosas, toda vida se encuentra en igualdad de condiciones.",
  str_guide_circle_2003001_LbT = "Características del enemigo",
  str_guide_circle_2003001_Lb = "Acumula Moretones al recibir daño. Inflige daño a todos los objetivos dentro del alcance de ataque, causando Quemaduras en ellos y creando incendios.",
  str_guide_circle_2003401_RtT = "Soldado Illumina Corrompido",
  str_guide_circle_2003401_Rt = "Una vez aliados, ahora enemigos, tal es el temor del Eclipse. La única misericordia que queda es darles descanso.",
  str_guide_circle_2003401_LbT = "Características del enemigo",
  str_guide_circle_2003401_Lb = "Si el HP está por debajo del 40% al inicio de una ronda, la unidad aumenta su ACT y DEF y cambia su estilo de ataque.",
  str_guide_circle_2003101_RtT = "Sargento de Illumina",
  str_guide_circle_2003101_Rt = "Como oficiales de base del ejército Illumina, son responsables de dirigir a los soldados regulares en el campo de batalla. La mayoría de ellos se gradúan de academias militares, mientras que unos pocos selectos son ascendidos de las filas de veteranos experimentados.",
  str_guide_circle_2003101_LbT = "Características del enemigo",
  str_guide_circle_2003101_Lb = "Su presencia mejora las habilidades de los Soldados Illumina cercanos y les ayuda a recuperar de sus heridas. Si se encuentran aislados de sus aliados o en espacios cerrados con enemigos, estos sargentos toman las armas, infligiendo daño con cortes devastadores y patadas impactantes.",
  str_guide_circle_2003101_RbT = "Estrategia de afrontamiento",
  str_guide_circle_2003101_Rb = "¡Derrota primero al comandante enemigo!",
  str_guide_circle_2905701_RtT = "Mudbundle",
  str_guide_circle_2905701_Rt = "Se rumorea que es una creación de un miembro de Eclipse, este Eclipsite es una fusión de varias características biológicas. Crea temibles pantanos que pueden devorar todo y contaminar todo lo que tocan.",
  str_guide_circle_2905701_LbT = "Características del enemigo",
  str_guide_circle_2905701_Lb = "Crea atolladeros y sumersiones en su interior, obstruyendo e interrumpiendo los movimientos de los aurorianos en su interior, alterando el terreno.",
  str_guide_circle_2905701_RbT = "Estrategia de afrontamiento",
  str_guide_circle_2905701_Rb = "Evita pasar por demasiados lodazales. ¡Usa tus habilidades para limpiar el campo!",
  str_guide_circle_29057011_RtT = "Pantano",
  str_guide_circle_29057011_Rt = "Contaminando todo lo que ha visto...",
  str_guide_circle_29057011_LbT = "Características",
  str_guide_circle_29057011_Lb = "Al pasar por un cierto número de lodazales, se aumentará el tiempo de reutilización de las Habilidades Activas de todos los Aurorianos.",
  str_guide_circle_29057011_RbT = "Estrategia de afrontamiento",
  str_guide_circle_29057011_Rb = "Se puede limpiar con habilidades de daño de área de los aurorianos",
  str_guide_warn_815000101 = "¿Por qué aún no puedo liberarme de este sueño? ¿Es por culpa de Paloma... sigue atrapada en él?\nToca el botón Cambiar para pasar al Modo Exploración. Navegante, ¿puedes ayudar a Paloma como me ayudaste a mí?",
  str_guide_warn_815000102 = "Toca el botón Cambiar de nuevo para volver al Modo Revelar. ¡Navegador, parece que podemos regresar a mi sueño cuando queramos!",
  str_guide_circle_80020201 = "Toca la balanza aquí para ayudarme a sumergirme en una contemplación y deducción más profundas. Solo después de completar mis deducciones puedo continuar con las tareas asignadas por el Juez Principal.",
  str_guide_circle_80020202 = "Sin embargo, antes de comenzar la deducción, debo reunir suficientes pruebas, testimonios... Observa de cerca. ¡Las pistas cruciales deben estar cerca!",
  ["str_guide_circle_CN5-15_Lt"] = "Heredando las sinceras enseñanzas de su padre y cumpliendo con todas sus expectativas, se ha convertido en la perfecta Irridon, ¡la más grande juez principal jamás conocida!",
  ["str_guide_circle_CN5-15_LtT"] = "Irridon: Eximius",
  ["str_guide_circle_CN5-15_Rt"] = "Antes de cada Chain Combo, forma un Escudo de Luz, bloqueando daño equivalente a un porcentaje del HP máximo.",
  ["str_guide_circle_CN5-15_RtT"] = "Escudo de luz",
  ["str_guide_circle_CN5-15_Lb"] = "Manipular y engañar a otros con sus clones, estos trucos apenas son deshonrosos en sus ojos; después de todo, ella tiene la máxima autoridad como la más grande Jueza Jefa.",
  ["str_guide_circle_CN5-15_LbT"] = "Irridon: Clon Eximius",
  ["str_guide_circle_CN5-15_Rb"] = "El daño infligido a Irridon: Clones Eximius se transfiere instantáneamente a Irridon: Eximius.",
  ["str_guide_circle_CN5-15_RbT"] = "Transmisión de daños",
  ["str_guide_circle_CN5-18_Lb"] = "Situado fuera del campo, inmune a ataques normales, sólo puede ser atacado por habilidades de un solo objetivo.",
  ["str_guide_circle_CN5-18_LbT"] = "Irridon: Clon Eximius",
  ["str_guide_circle_CN5-diaoxiang_Lt"] = "Estatua noble arrogante. Inflige 1 acumulación de Prejuicio a los aliados y se desmorona al tocarla, transformando la casilla en la que estaban en una casilla cromática y eliminando 1 acumulación de Prejuicio.",
  ["str_guide_circle_CN5-diaoxiang_LtT"] = "Estatua del jurado",
  ["str_guide_circle_CN5-4_Rb"] = "Enemigos específicos poseen el efecto Escudo de Luz. Antes de cada Combo en Cadena, forman el Escudo de Luz, bloqueando daño igual a un porcentaje de su HP máxima.",
  ["str_guide_circle_CN5-4_RbT"] = "Escudo de luz",
  ["str_guide_circle_CN5-8_Lt"] = "Arrogancia, prejuicio y pensamientos corruptos... se han solidificado en espectros malévolos que deambulan por Lumopolis, infiltrándose en cada rincón de esta ciudad eterna.",
  ["str_guide_circle_CN5-8_LtT"] = "Espectro Carmesí",
  ["str_guide_circle_CN5-8_Lb"] = "Puede teletransportarse a la ubicación del jugador más cercano, infligiendo múltiples golpes dañinos y haciendo retroceder al jugador. Cuanto más lejos se teletransporte, menos ataques lanzará.",
  ["str_guide_circle_CN5-8_LbT"] = "Características del enemigo",
  ["str_guide_circle_CN5-8_Rb"] = "El Espectro Carmesí puede alterar las posiciones de los jugadores, por lo que es recomendable eliminarlo rápidamente o alejarse de él.",
  ["str_guide_circle_CN5-8_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_n35-7_LtT"] = "Bestia Escarcha",
  ["str_guide_circle_n35-7_Lt"] = "Con pelaje y garras afiladas, este tipo de Eclipsites tiene un sorprendente parecido con bestias salvajes, lo que los hace muy adecuados para infiltrarse en diversas regiones fronterizas para rastrear, explorar y cazar.",
  ["str_guide_circle_n35-7_Lb"] = "Selecciona diferentes habilidades según la posición del Aurorian, y si su ataque no puede alcanzar a ningún Aurorian, optará por recuperar su propio HP.",
  ["str_guide_circle_n35-7_LbT"] = "Características del enemigo",
  ["str_guide_circle_n35-7_Rb"] = "Vigila el alcance de ataque de los Eclipsites y siempre ten en cuenta la posición de nuestros aliados.",
  ["str_guide_circle_n35-7_RbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_n35-9_LtT"] = "No. 33",
  ["str_guide_circle_n35-9_Lt"] = "Un Aurorian del pasado lejano, encargado de proteger las ruinas subterráneas de Northland. Su Plantilla de Eco sigue produciendo errores debido al daño que ha sufrido y su activación poco ortodoxa.",
  ["str_guide_circle_n35-9_Lb"] = "Capaz de teletransportarse y alterar la disposición de las losetas, así como absorber la energía de las losetas para atacar a los aurorianos. Cuantas más losetas disponibles para absorber energía, mayor será el daño.",
  ["str_guide_circle_n35-9_LbT"] = "Características del enemigo",
  ["str_guide_circle_n35-9_Rb"] = "¡Presta atención a la distribución de casillas en el campo de batalla y ten cuidado con cuándo el enemigo usa habilidades!",
  ["str_guide_circle_n35-9_RbT"] = "Estrategia de afrontamiento",
  str_guide_circle_n35_trap5352031_RtT = "Bomba fatal",
  str_guide_circle_n35_trap5352031_Rt = "Explota cada cierto tiempo, infligiendo daño a todas las unidades en el campo de batalla.",
  str_guide_circle_n35_trap5352031_RbT = "Estrategia de afrontamiento",
  str_guide_circle_n35_trap5352031_Rb = "Ordena a tus Aurorianos derrotar a los enemigos lo más pronto posible, o recibirás daño con el tiempo.",
  str_guide_warn_53540034 = "Aquí se muestra la cuenta regresiva restante para el Reino.",
  str_guide_warn_16000101 = "¡Un Enigma Sellado en Hielo ya está disponible! ¡Es hora de conocer nuevos socios y embarcarse en la aventura en la expedición Through the Snow!",
  str_guide_warn_16000102 = "En Fatal Trek nos enfrentaremos a una serie de desafíos más complejos.",
  str_guide_warn_16000103 = "En el evento Ancient Yurt, podremos intercambiar Ancient Remains por Solamber, Aurorianos de 5 estrellas y otros objetos valiosos. Los restos antiguos se pueden obtener completando etapas del evento y consumiendo Prisma.",
  str_guide_warn_16000104 = "Estará disponible el nuevo modo Armario de Zarya. ¡Toca la entrada de este nuevo modo de juego para explorarlo!",
  str_guide_warn_16000105 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_16000106 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas diarias por inicio de sesión.",
  str_guide_warn_16000107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_9700101 = "La lista de deseos está disponible en este reclutamiento por tiempo limitado. Toque para abrir la interfaz de la lista de deseos.",
  str_guide_warn_9700106 = "La Wishlist está disponible exclusivamente en la contratación a la que pertenece.",
  str_guide_warn_9700107 = "En este reclutamiento, hay un Auroriano que presenta una probabilidad de obtención aumentada que se fija en el primer lugar de la Lista de deseos, con un 50 % de probabilidad en todos los Aurorianos de 6 estrellas disponibles.",
  str_guide_warn_9700108 = "Seleccione un Auroriano de 6 estrellas de cada uno de los cuatro elementos, y cada uno de ellos tendrá un 12,5% de posibilidades de obtener Aurorianos de 6 estrellas.",
  ["str_guide_circle_n36-9_LtT"] = "Emperador de la Muerte",
  ["str_guide_circle_n36-9_Lt"] = "El Emperador Supremo del Caos, padre de Tohru, un veterano de muchas guerras, es una fuerza indiscutible sin importar cuándo y dónde.",
  ["str_guide_circle_n36-9_Lb"] = "Con una fuerza formidable, maneja una multitud de habilidades para atacar a los jugadores con precisión o desatar ataques de amplio alcance, mientras los derriba.",
  ["str_guide_circle_n36-9_LbT"] = "Características del enemigo",
  ["str_guide_circle_n36-9_Rb"] = "El Emperador de la Muerte puede ser influenciado por las habilidades de derribo o teletransporte del jugador. Desplazarlo en el momento adecuado permite al jugador evadir o interrumpir sus habilidades de ataque.",
  ["str_guide_circle_n36-9_RbT"] = "Estrategia de afrontamiento",
  str_guide_warn_17000101 = "¡El Día Libre de Sirvienta Dragón ya está disponible! Es hora de conocer nuevos amigos y embarcarse en una nueva aventura en El Camino a Casa!",
  str_guide_warn_17000102 = "Gasta Prisma en las etapas principales y de Incursión de Recursos para Platos de Cena.",
  str_guide_warn_17000103 = "Usa Platos de Cena para recibir una variedad de recompensas en la Cocina de Tohru.",
  str_guide_warn_17000104 = "Durante el evento, ¡únete a la Fiesta del Té Caelestite para participar en cuestionarios de camaradería con Aurorianos!",
  str_guide_warn_17000105 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas por inicio de sesión.",
  str_guide_warn_17000106 = "¡Acepta una serie de desafíos de eventos y completa las misiones de tu libro de eventos especiales!",
  str_guide_warn_17000107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_18000101 = "¡Venom Flows Through Corrupted Hearts ya está disponible! ¡Es hora de conocer nuevos amigos y embarcarte en una nueva aventura en la Clínica Subterránea!",
  str_guide_warn_18000102 = "En Bleak Past, nos enfrentaremos a una serie de desafíos más complejos.",
  str_guide_warn_18000103 = "Completar etapas del evento y gastar Prism otorga Frascos de Colección que se pueden usar para canjear varias recompensas de The Secret Room.",
  str_guide_warn_18000104 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_18000105 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas diarias por inicio de sesión.",
  str_guide_warn_18000106 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  ["str_guide_circle_CN7-15_Lt"] = "Del mundo superficial al pueblo submarino, un noble dominante y villano.",
  ["str_guide_circle_CN7-15_LtT"] = "Rey Tritón",
  ["str_guide_circle_CN7-15_Rt"] = "Los ataques infligen retroceso. Puede invocar cañones de salva en el borde del campo de batalla.",
  ["str_guide_circle_CN7-15_RtT"] = "Características del enemigo",
  ["str_guide_circle_CN7-15_Lb"] = "Presta atención al alcance de ataque de las ametralladoras en el campo de batalla. Derrota a la artillería de manera oportuna para terminar rápidamente la batalla.",
  ["str_guide_circle_CN7-15_LbT"] = "Estrategia de afrontamiento",
  ["str_guide_circle_CN7-5_Lt"] = "Un Eclipsite que se asemeja a un cañón de arma. ¡Proporciona apoyo a sus compañeros y ataca fuertemente a tu equipo!",
  ["str_guide_circle_CN7-5_LtT"] = "Cañón Salva",
  ["str_guide_circle_CN7-5_Rt"] = "Ataca a enemigos dentro del alcance de ataque. Si no hay objetivos disponibles, su ataque se potencia y cura al Rey Tritón.",
  ["str_guide_circle_CN7-5_RtT"] = "Cañón pesado",
  ["str_guide_circle_CN7-7_Lt"] = "Los aliados no pueden conectarse a través de él, tampoco las unidades enemigas terrestres, pero esto no afectará el efecto de ninguna habilidad lanzada.",
  ["str_guide_circle_CN7-7_LtT"] = "Muro Prohibido",
  str_guide_circle_80030101 = "Con binoculares, puedes ver el gran castillo a lo lejos: el templo del Señor del Agua.",
  str_guide_warn_80030102 = "Toca el botón de Construcción del Templo y Connolly se dirigirá a un lugar con una vista perfecta del templo, junto con sus tentáculos de confianza, para continuar con el proyecto de restauración del templo.",
  str_guide_warn_80030301 = "Navegador, ¡bienvenido al Ritual de Fusión! Coloca el Fragmento de Aqua en el área de fusión en el centro del Ritual de Fusión para ayudarme a completar el ritual, ¡restaurando la fuerza de Antons!",
  str_guide_warn_80030302 = "El Fragmento de Aqua contiene el poder de Anton. Cada Fragmento tiene una cantidad diferente de poder de fusión. Bajo condiciones específicas, algunos fragmentos podrían liberar poder adicional.",
  str_guide_warn_80030303 = "Arrastra el Fragmento de Aqua a un lugar elegible en el área de fusión. Una vez colocado con éxito, el Ritual de Fusión guiará y extraerá el poder de fusión contenido en él.",
  str_guide_warn_80030304 = "Después de colocar con éxito el Fragmento de Aqua, puedes tocarlo para seleccionar y moverlo o ajustarlo. Explora diferentes ubicaciones para aprovechar al máximo su poder de agregación.",
  str_guide_warn_80030305 = "Mientras esté seleccionado, toca el botón Girar para rotar el fragmento 90 grados en sentido antihorario.",
  str_guide_warn_80030306 = "Mientras esté seleccionado, toca el botón Cancelar para recuperar el fragmento.",
  str_guide_warn_80030307 = "¡Aquí, encontrarás la potencia de fusión total contenida en los Fragmentos de Aqua colocados actualmente y la potencia de fusión necesaria para completar este Ritual de Fusión!",
  str_guide_warn_80030308 = "Toca el botón Borrar para eliminar todos los fragmentos de Aqua colocados. ¡Ten cuidado!",
  str_guide_warn_80030309 = "Cuando la energía de fusión cumpla con los requisitos para el Ritual de Fusión, ¡toca el botón Completar para terminar el ritual y restaurar la fuerza de Anton!",
  str_guide_warn_18100101 = "¡Por favor, ayúdame a ver! ¿Qué demonios está pasando aquí!",
  str_guide_warn_18100102 = "¡Aquí es donde puedes comenzar tu entrenamiento! ¡Completa las etapas de entrenamiento para ganar puntos y recompensas de etapa!",
  str_guide_warn_18100103 = "Tenga en cuenta: Durante el módulo de entrenamiento, existen lazos entre ciertos Aurorians. Cuando se despliegan Aurorians con un vínculo al mismo tiempo, tendrán más oportunidades de participar en combate.",
  str_guide_warn_18100104 = "Cuando se despliegan al menos 3 Aurorians de una facción designada, eliminar varias fichas a la vez durante el entrenamiento puede activar habilidades de apoyo de la facción.",
  str_guide_warn_18100105 = "Al completar el entrenamiento, ganarás puntos y, una vez que alcances un número especificado de puntos por sesión, obtendrás recompensas especiales.",
  str_guide_warn_18100106 = "Al completar las etapas de entrenamiento, ganarás recompensas. La cantidad máxima de recompensas que puedes obtener en cada sesión se mostrará aquí.",
  str_guide_warn_18100107 = "Si tienes alguna pregunta, puedes ver la descripción detallada aquí.",
  str_guide_warn_18100108 = "El número total de rondas en cada ciclo de entrenamiento es limitado, y el PS total de los equipos se acumulará de etapa en etapa.",
  str_guide_circle_N37boss_Lt = "Sus venas palpitan con veneno carmesí, listas para erradicar cualquier amenaza para su familia, incluyéndose a sí misma.",
  str_guide_circle_N37boss_LtT = "Rebecca Pantano venenoso",
  str_guide_circle_N37boss_Rt = "Inflige el efecto de Fusión, haciendo que los objetivos afectados pierdan HP al comenzar sus rondas.",
  str_guide_circle_N37boss_RtT = "Características del enemigo",
  str_guide_circle_N37boss_Lb = "Aprovecha al máximo las Casillas Oscuras transformadas por las Marcas de Veneno e inflige daño en el momento adecuado.",
  str_guide_circle_N37boss_LbT = "Estrategia de afrontamiento",
  str_guide_circle_N37cap_Lt = "El peculiar líder de una pandilla, experto en armas de fuego. Su presencia solo significa problemas para Umbraton.",
  str_guide_circle_N37cap_LtT = "Capitán de la pandilla",
  str_guide_circle_N37cap_Rt = "Ataca después de alejarse del objetivo, infligiendo daño 2 veces. Puede robar los atributos del objetivo.",
  str_guide_circle_N37cap_RtT = "Características del enemigo",
  str_guide_circle_N37cap_Lb = "Presta atención a la distancia entre ellos y derrota a los enemigos a tiempo.",
  str_guide_circle_N37cap_LbT = "Estrategia de afrontamiento",
  str_guide_circle_N37ranger_Lt = "Precisas, seguras, discretas e increíblemente poderosas, las ballestas se han convertido en un arma muy apreciada entre los gángsters debido a estas propiedades inigualables. Los enemigos expertos en su uso suelen ser altamente peligrosos.",
  str_guide_circle_N37ranger_LtT = "Ballestero de pandilla",
  str_guide_circle_N37ranger_Rt = "Puede atacar objetivos en forma de cruz hasta el máximo de su alcance. Después de golpear, reduce la curación recibida por el objetivo.",
  str_guide_circle_N37ranger_RtT = "Características del enemigo",
  str_guide_circle_N37ranger_Lb = "Acércate rápidamente y prioriza eliminarlos.",
  str_guide_circle_N37ranger_LbT = "Estrategia de afrontamiento",
  str_guide_circle_N37light_Lt = "Un miembro de la pandilla corpulento de inmensa fuerza, hábil en el uso de sus brazos mecánicos para el combate. Además, puede ofrecer apoyo a otras fuerzas enemigas de Umbraton en el campo.",
  str_guide_circle_N37light_LtT = "Especialista en apoyo a pandillas",
  str_guide_circle_N37light_Rt = "Proporciona un aumento de ATK a los miembros de Umbraton dentro de 1 grupo circundante; se cura a sí mismo cuando su HP cae por debajo de cierto porcentaje.",
  str_guide_circle_N37light_RtT = "Características del enemigo",
  str_guide_circle_N37light_Lb = "Elimínalos de un solo golpe para evitar su continua auto-curación.",
  str_guide_circle_N37light_LbT = "Estrategia de afrontamiento",
  str_guide_circle_n37_trap2803501_RtT = "Casilla Oscura",
  str_guide_circle_n37_trap2803501_Rt = "El siguiente mosaico en esta ubicación está garantizado de ser del mismo elemento que el mosaico actual.",
  str_guide_circle_n37_trap2803501_RbT = "Estrategia de afrontamiento",
  str_guide_circle_n37_trap2803501_Rb = "Utiliza habilidades de conversión de casillas para cambiar los elementos de las casillas y maximizar sus efectos.",
  str_guide_circle_N37cike_LtT = "Asesino de pandillas",
  str_guide_circle_N37cike_Lt = "Lanza 2 golpes consecutivos rápidos contra el enemigo y roba los atributos del objetivo.",
  str_guide_circle_N37cike_Lb = "Derrota a los enemigos lo más rápido posible. No dejes que te ataquen continuamente.",
  str_guide_circle_N37cike_LbT = "Estrategia de afrontamiento",
  str_guide_warn_551105 = "¡Toca aquí!",
  str_guide_warn_551106 = "El sistema de Iluminación ha sido activado. Los atributos de los Aurorian ahora pueden mejorarse de manera integral. Toca para entrar al Módulo de Agua.",
  str_guide_warn_551107 = "La lista a la izquierda te permite cambiar rápidamente entre Módulos de diferentes Elementos.",
  str_guide_warn_551108 = "Vea el nivel y progreso de este Módulo de Elemento aquí.",
  str_guide_warn_551109 = "Ver detalles de actualización del módulo aquí.",
  str_guide_warn_551110 = "Si tienes alguna pregunta, puedes ver la descripción detallada aquí.",
  str_guide_warn_19000101 = "Aquí, puedes rescatar tesoros, trayendo valiosas reliquias de los barcos hundidos a la superficie una por una.",
  str_guide_warn_19000102 = "Las reliquias encontradas se documentarán en este Archivo de Reliquias. Ábrelo para acceder a los registros relacionados.",
  str_guide_warn_19000103 = "Si tienes alguna pregunta, no dudes en consultar las instrucciones de ayuda aquí para aclaraciones.",
  str_guide_warn_19000104 = "Toca las reliquias en el campo para moverlas al área de recuperación abajo.",
  str_guide_warn_19000105 = "Cuando el número de reliquias idénticas en el área de rescate alcance 3, la reliquia se rescatará con éxito y se eliminará de las ranuras.",
  str_guide_warn_19000106 = "Aquí, utiliza la función de almacenamiento de reliquias para mover las reliquias de las ranuras de rescate al campo, evitando fallos porque todas las ranuras están llenas.",
  str_guide_cage_Rt = "Puede ser aplastado por las habilidades de daño de área de los Aurorianos. ¡Pueden aparecer nuevos enemigos después de que sea aplastado!",
  str_guide_cage_RtT = "Trampa especial - Jaula",
  str_guide_circle_N38boss_Lt = "Un arma peligrosa creada al combinar las características mortales de muchas creaciones mecánicas, incluida la tecnología de Astra. Las fuentes de energía ordinarias no pueden mantener en funcionamiento a esta gigantesca criatura.",
  str_guide_circle_N38boss_LtT = "Agujón: Coalescencia",
  str_guide_circle_N38boss_Rt = "Cada Bestia Mecánica que forma parte de su cuerpo tiene su propio ataque único. La cola puede acumular Energía para infligir daño garantizado a sus objetivos, pero también es relativamente frágil.",
  str_guide_circle_N38boss_RtT = "Características del enemigo",
  str_guide_circle_N38boss_Lb = "Ataca su cola con Aurorians Francotiradores primero para inmovilizarlo temporalmente, luego aprovecha esta oportunidad para infligir daño.",
  str_guide_circle_N38boss_LbT = "Estrategia de afrontamiento",
  str_guide_warn_13800101 = "¡Etched Upon the Ocean Drifting Begonia I ya está disponible!\n¡Es hora de conocer nuevos amigos y embarcarse en una nueva aventura en The Homecoming!",
  str_guide_warn_13800102 = "Gasta Prisma en las etapas de la historia principal y de Incursión de Recursos para obtener pagarés de Lin Guild.",
  str_guide_warn_13800103 = "En Lost Ship At Sea, nos enfrentaremos a una serie de desafíos más complejos.",
  str_guide_warn_13800104 = "En The Docks, usa los pagarés del gremio Lin para canjear diversas recompensas.",
  str_guide_warn_13800105 = "Recuerda iniciar sesión en el juego todos los días para obtener recompensas de inicio de sesión en Berth.",
  str_guide_warn_13800106 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_13800107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_crab_Rt = "Esta creación de herramienta mecánica fue diseñada para ayudar a los artesanos a hacer inventos ingeniosos. Más tarde, fue modificada para que una variación de esta invención pudiera almacenar Fuerza de Llama en su vientre. Nunca se pretendió que se usara como un arma.",
  str_guide_crab_RtT = "Cangrejo forjado en horno",
  str_guide_crab_Lt = "Se mueve lateralmente mientras escupe llamas para atacar a los objetivos que tiene delante.",
  str_guide_crab_LtT = "Características del enemigo",
  str_guide_crab_Lb = "El Cangrejo Forjado en Horno tiene un patrón de movimiento fijo y no puede darse la vuelta, así que colócate detrás de él antes de empezar a infligir daño.",
  str_guide_crab_LbT = "Estrategia de afrontamiento",
  str_guide_warn_13900101 = "¡Sombras Debajo de la Oscuridad ya está disponible!\n¡Es hora de conocer nuevos amigos y embarcarte en una nueva aventura en Bajo las Sombras!",
  str_guide_warn_13900102 = "Gasta Prisma en las etapas de la historia principal y de Incursión de Recursos para obtener Tokens de Cloudrover.",
  str_guide_warn_13900103 = "En Deadly Arena, nos enfrentaremos a una serie de desafíos más complejos.",
  str_guide_warn_13900104 = "En la Nave Aérea de Explorador Nublar, usa los Tokens de Explorador Nublar para canjear diversas recompensas.",
  str_guide_warn_13900105 = "Recuerda iniciar sesión en el juego todos los días para obtener las recompensas de inicio de sesión para visitantes.",
  str_guide_warn_13900106 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_13900107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_circle_S4boss_Lt = "Una espada hábilmente forjada nacida de la ingeniosidad del Reino Ye de Longzhou. Originalmente fue diseñada como un arma de autodefensa para aquellos que no sabían cómo defenderse con una espada, pero ahora se ha convertido en una maldita espada maligna después de caer en manos de villanos.",
  str_guide_circle_S4boss_LtT = "Vilanor: Trampa Maldita",
  str_guide_circle_S4boss_Rt = "Después de convertirse en Vilanor, sus habilidades se mejoran enormemente, obteniendo el poder de moverse libremente por el campo y generar espadas a partir de la energía maligna.",
  str_guide_circle_S4boss_RtT = "Características del enemigo",
  str_guide_circle_S4boss_Lb = "Vilanor tiene la capacidad de abrir el espacio y crear Muros Prohibidos, por lo que puedes usar a los aurorianos que tienen habilidades de teletransportación para pisar las Trampas de Exorcismo y atacar a Vilanor fácilmente después de eliminar los Muros Prohibidos.",
  str_guide_circle_S4boss_LbT = "Estrategia de afrontamiento",
  str_guide_warn_16021911 = "Es necesario seleccionar 1 aliado o Pieza de Sombra para usar Istvan: la Habilidad Activa de Pith Marcado.",
  str_guide_warn_16021912 = "Aquí es donde puedes ver el número de Dotaciones de Sombra utilizadas por el aliado actual. No se puede lanzar en este aliado si se ha utilizado un número insuficiente.",
  str_guide_warn_16021913 = "Lanza la habilidad en Areia.",
  str_guide_warn_16021914 = "En esta batalla, el costo de esta habilidad aumenta +1 cada vez que se lanza una Habilidad Activa sobre este aliado.",
  str_guide_warn_80040111 = "¡Navegante, mira aquí! ¡Has ganado una nueva habilidad en el Sueño!",
  str_guide_warn_80040112 = "Tus habilidades se fortalecerán a medida que te adentres más en los sueños. ¡Haz buen uso de ellas!",
  str_guide_circle_shenghuaboss_Lt = "Este súper soldado es un Eclipsite que ha sido equipado con dispositivos mecánicos por todo su cuerpo para hacerlo más resistente, más feroz y más intimidante.",
  str_guide_circle_shenghuaboss_LtT = "Super-Soldado Blaugm",
  str_guide_circle_shenghuaboss_Rt = "Un intimidante súper soldado que sobresale en aplastar a los enemigos cercanos con sus ataques.",
  str_guide_circle_shenghuaboss_RtT = "Características del enemigo",
  str_guide_circle_shenghuaboss_Lb = "Blaugm tiene una alta resistencia al daño de Ataque Normal, así que intenta infligir daño con Combos en Cadena o Hab. Activas.",
  str_guide_circle_shenghuaboss_LbT = "Estrategia de afrontamiento",
  str_guide_circle_ylxs_Lt = "Ulysses modificó su cuerpo extensamente para realizar sus ideales extremos. Ya no es un Aurorian ahora.",
  str_guide_circle_ylxs_LtT = "Ulysses Bio",
  str_guide_circle_ylxs_Rt = "Ulysses utiliza diferentes estrategias de ataque basadas en las habilidades de los Aurorianos.",
  str_guide_circle_ylxs_RtT = "Características del enemigo",
  str_guide_circle_ylxs_Lb = "Basándote en la condición actual del equipo, ataca sabiamente y evita recibir daño de Ulysses para aumentar enormemente las posibilidades de victoria.",
  str_guide_circle_ylxs_LbT = "Estrategia de afrontamiento",
  str_guide_warn_shzyx_01 = "¡Advertencia! El Prototipo del Guardián ha sido activado.",
  str_guide_warn_shzyx_02 = "Esta máquina antigua construida por el Ingeniero parece ser consciente de sí misma.",
  str_guide_warn_shzyx_03 = "Restringe los Ataques Normales, Habilidades Activas o Combos en Cadena de los Aurorians. También daña a los enemigos y protege a los aliados al mismo tiempo.",
  str_guide_warn_shzyx_04 = "Basándote en la condición actual del equipo, ataca sabiamente para tener la oportunidad de enfrentarte a él. ¡No lo subestimes!",
  str_guide_circle_soilder1_Rt = "Una arma de guerra creada a través de la fusión de Eclipsites y Aurorianos. Se han conservado las características de los Aurorianos tanto como fue posible, y la mecanización no es demasiado obvia, pero sigue siendo muy peligrosa.",
  str_guide_circle_soilder1_RtT = "Soldado Voidcross",
  str_guide_circle_soilder1_Rb = "Una forma de vida mecánica que ataca hackeando y cortando.",
  str_guide_circle_soilder1_RbT = "Características del enemigo",
  str_guide_circle_soilder1_Lb = "El Soldado Voidcross puede reflejar el daño del Ataque Normal de los Aurorians. Mantén tu distancia e intenta infligir daño con Combos en Cadena o Habilidades Activas.",
  str_guide_circle_soilder1_LbT = "Estrategia de afrontamiento",
  str_guide_circle_soilder2_Rt = "Una arma de guerra creada a través de la fusión de Eclipsites y Aurorianos. Está protegida por una gruesa capa de armadura mecánica, y su fuerza ha sido mejorada al máximo posible.",
  str_guide_circle_soilder2_RtT = "Soldado Ululat",
  str_guide_circle_soilder2_Rb = "El poder y la defensa de esta forma de vida mecánica modificada han mejorado enormemente, y sobresale en atacar con explosiones y otros métodos similares.",
  str_guide_circle_soilder2_RbT = "Características del enemigo",
  str_guide_circle_soilder2_Lb = "El soldado Ululat puede reflejar el daño del Ataque Normal de los Aurorians. Presta atención al rango de ataque e intenta infligir daño con Combos en Cadena o Habilidades Activas.",
  str_guide_circle_soilder2_LbT = "Estrategia de afrontamiento",
  str_guide_circle_soilder3_Rt = "Una super arma creada a través de la fusión de Eclipsites y Aurorians. Ya no tiene características Aurorianas y ahora es una existencia completamente mecánica.",
  str_guide_circle_soilder3_RtT = "Super-Soldado Meaugm",
  str_guide_circle_soilder3_Rb = "Esta forma de vida mecánica modificada puede usar su gruesa armadura como arma, lo que la hace muy difícil de manejar.",
  str_guide_circle_soilder3_RbT = "Características del enemigo",
  str_guide_circle_soilder3_Lb = "El Súper-Soldado Meaugm puede reflejar el daño del Ataque Normal de los Aurorianos y restaurar su propio HP, así que intenta terminar la batalla lo más rápido posible.",
  str_guide_circle_soilder3_LbT = "Estrategia de afrontamiento",
  str_guide_warn_14000101 = "A través de la niebla, Eco del pasado ya está disponible!\n¡Comencemos una nueva historia en la Parte 2!",
  str_guide_warn_14000102 = "Los capítulos de la historia que se desbloquean en este evento, así como los capítulos que se han explorado hasta ahora, se muestran aquí.",
  str_guide_warn_14000103 = "Toca \"Explorar ahora\" para ir directamente al mapa de exploración. Gasta Prisma en las etapas de la historia principal y de Incursión de Recursos para obtener Plumas de Caelestite.",
  str_guide_warn_14000104 = "En Aurora Exchange, usa las Plumas Caelestite para canjear varias recompensas.",
  str_guide_warn_14000105 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_14000106 = "Recuerda iniciar sesión en el juego todos los días para obtener las recompensas de Navegación por inicio de sesión.",
  str_guide_warn_14000107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_14100101 = "¡Drifting Begonia II: Cometh the Dragon, Spirits Begone ya está disponible! ¡Es hora de conocer nuevos amigos y embarcarse en una nueva aventura en Dragon's Dance!",
  str_guide_warn_14100102 = "Gasta Prisma en las etapas de la historia principal y de Incursión de Recursos para Incienso de Oración.",
  str_guide_warn_14100103 = "En Absconding Evil, nos enfrentaremos a una serie de desafíos más complejos.",
  str_guide_warn_14100104 = "En Bendiciones del Mar, usa Incienso de Oración para canjear diversas recompensas.",
  str_guide_warn_14100105 = "Recuerda iniciar sesión en el juego todos los días para obtener las recompensas de inicio de sesión para visitantes.",
  str_guide_warn_14100106 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_warn_14100107 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_circle_yingzi_LtT = "Voluntad Malvada: Sombra",
  str_guide_circle_yingzi_Lt = "Manchado por la Mala Voluntad, sus poderes de invocación han cambiado sutílmente.",
  str_guide_circle_yingzi_RtT = "Características del enemigo",
  str_guide_circle_yingzi_Rt = "El número de runas invocadas cada vez aumenta significativamente.",
  str_guide_circle_miran_LtT = "Voluntad Malvada: Murkmite",
  str_guide_circle_miran_Lt = "Manchado por la Voluntad Malvada, sus ataques han cambiado sutílmente.",
  str_guide_circle_miran_RtT = "Características del enemigo",
  str_guide_circle_miran_Rt = "Al golpear, su ataque reduce inmediatamente el Punto de Fuerza del jugador en 2.",
  str_guide_circle_aogeyang_LtT = "Malvado Voluntad: Augean",
  str_guide_circle_aogeyang_Lt = "Contaminado por la Mala Voluntad, su habilidad ha cambiado sutílmente.",
  str_guide_circle_aogeyang_RtT = "Características del enemigo",
  str_guide_circle_aogeyang_Rt = "Obtiene un aumento significativo en la movilidad y, cada 2 rondas, convoca monstruos al área cercana para atacar al jugador juntos.",
  str_guide_circle_jingmianta_LtT = "Torre reflectora: Vitalizada",
  str_guide_circle_jingmianta_Lt = "Dispositivo espejo que se transforma en entornos especiales, ofreciendo asistencia a los equipos aurorianos.",
  str_guide_circle_jingmianta_RtT = "Características de la trampa",
  str_guide_circle_jingmianta_Rt = "Posicionarse en el campo proporciona energía especial al equipo, la recuperación de Punto de Fuerza por ronda +1.",
  str_guide_circle_laolong_LtT = "Voluntad Malvada: Jaula",
  str_guide_circle_laolong_Lt = "Dentro de la jaula hay enemigos encarcelados por razones particulares. Una vez liberados, pueden ser de ayuda para el Jefe o exponer la vulnerabilidad del Jefe.",
  str_guide_circle_laolong_RtT = "Características de la trampa",
  str_guide_circle_laolong_Rt = "Toca la trampa y gasta 3 Puntos de Fuerza para liberar a los enemigos de la jaula. Aunque no te ayudarán en la batalla, el daño que reciban se transferirá parcialmente al Jefe.",
  str_guide_circle_paotai_LtT = "Torreta Ágil",
  str_guide_circle_paotai_Lt = "Una torreta de alto rendimiento. Aunque requiere operación manual, potencialmente es más efectiva que las automatizadas.",
  str_guide_circle_paotai_RtT = "Características de la trampa",
  str_guide_circle_paotai_Rt = "Toca la trampa y gasta 2 Puntos de Fuerza para lanzar 1 ataque, infligiendo daño y debilitamientos a los enemigos en una línea recta adelante.",
  str_guide_circle_fengchuan_RtT = "Características de la trampa",
  str_guide_circle_fengchuan_Rt = "Se vuelve aún más portátil y fácil de usar, capaz de liberar habilidades consumiendo los Puntos de Fuerza del equipo.",
  str_guide_circle_8024001 = "En Purificando el Mal en la Noche Quieta, el equipo ya no se mueve según las reglas originales sino que consume Puntos de Fuerza para el movimiento.",
  str_guide_circle_8024002 = "Los puntos de fuerza actuales del jugador se muestran a la izquierda, donde se pueden ver vistas previas en tiempo real de los puntos de fuerza restantes durante las conexiones de fichas.",
  str_guide_circle_8024003 = "El movimiento anterior parece haber agotado tus Puntos de Fuerza. Pero no te preocupes; recibirás una cierta cantidad de Puntos de Fuerza al comienzo de cada ronda, y la reposición de la próxima ronda se mostrará en el extremo derecho.",
  str_guide_circle_8024004 = "Toca aquí para ver los efectos del talento activo actualmente.",
  str_guide_circle_8024005 = "Los Puntos de Fuerza no consumidos en cada ronda no desaparecerán al final de la ronda. A veces, puede ser una elección sabia guardar los Puntos de Fuerza de una ronda.",
  str_guide_season_talent_tree_1 = "La Selección de Destrezas está compuesta por varios Nodos de Formación y Destrezas y otorga bonificaciones adicionales. ¡Comencemos activando el primer Nodo de Formación!",
  str_guide_season_talent_tree_2 = "Toca Activar para consumir Energía Auspiciosa y activar el primer Nodo de Formación.",
  str_guide_season_talent_tree_3 = "Una vez que se activa un Nodo de Formación, sus efectos comenzarán a tener efecto en las batallas. También es posible desbloquear ranuras de habilidades en algunos Nodos de Formación.",
  str_guide_season_talent_tree_4 = "Ahora intentemos activar y equipar la primera Habilidad Pasiva. Por favor, toca esta Habilidad Pasiva.",
  str_guide_season_talent_tree_5 = "Toca Activar para consumir Energía Auspiciosa y activar este Don.",
  str_guide_season_talent_tree_6 = "Después de activar el Truco, arrástralo al espacio correspondiente para equiparlo y usar su efecto en la batalla.",
  str_guide_season_talent_tree_7 = "Las ranuras de habilidad tienen ciertas restricciones de tipo de habilidad. La primera ranura de habilidad solo puede equiparse con una habilidad de Caelestite, y las demás ranuras solo pueden equiparse con habilidades pasivas.",
  str_guide_season_talent_tree_8 = "Por favor, consulta la información del juego para más detalles sobre las reglas.",
  str_guide_season_trade_out_1 = "Daytime Merchant es un nuevo juego en el que los Navegantes pueden administrar un puerto y barcos para ganar Capital de Trabajo y Energía Auspiciosa.",
  str_guide_season_trade_out_2 = "Purging Evil in the Still Night es un nuevo juego con etapas lineales. En este juego, los navegantes se moverán de acuerdo con un nuevo sistema y usarán Trucos de Feng Shui para obtener ventajas en la batalla!",
  str_guide_season_trade_in_1 = "Los navegantes necesitarán gestionar puertos y barcos y pueden tocar Renovación Mejora en la esquina superior derecha para mejorar el objetivo seleccionado.",
  str_guide_season_trade_in_2 = "Los niveles del puerto y del barco afectarán la velocidad de descarga del puerto, la carga restante de los barcos y el tiempo requerido para descargar mercancías después de completar los viajes.",
  str_guide_season_trade_in_3 = "Los miembros de la tripulación contratados pueden ser asignados a varios barcos, pero cada miembro de la tripulación solo puede ser asignado a un barco a la vez.",
  str_guide_season_trade_in_4 = "Los miembros de la tripulación tienen atributos de Despacho, Capacidad de Envío y Preparación. Mejora los puertos para contratar miembros de la tripulación más capaces.",
  str_guide_season_trade_in_5 = "El estado del barco de cada nave se determina por los puntos de habilidad de los miembros de la tripulación asignados al barco. Si un barco no cumple con los requisitos de nivel del barco, su estado del barco será significativamente más bajo, lo que afectará sus ganancias.",
  str_guide_season_trade_in_6 = "¡Cumple con los diversos objetivos de etapa de Capital de Trabajo de los viajes para mejorar el Nivel de Prosperidad de la Guild y reclamar recompensas adicionales!",
  str_guide_season_trade_in_7 = "¡Esfuérzate por mejorar los puertos y barcos, asigna miembros de la tripulación adecuados a los barcos y responde adecuadamente a los incidentes de navegación para obtener más beneficios de los viajes!",
  str_guide_season_trade_in_8 = "Por favor, consulta la información del juego para más detalles sobre las reglas.",
  str_guide_mouse_Rt = "Fiendlings omnívoros de tamaño pequeño con una cultivación insuficiente, mantienen una naturaleza salvaje. Siempre se cuelan en las viviendas de los Aurorianos para robar comida. Algunos más agresivos incluso pueden causar daño.",
  str_guide_mouse_RtT = "Diablillo: Rata",
  str_guide_mouse_Lt = "Ágil y rápido, se mueve velozmente detrás del objetivo después de un ataque.",
  str_guide_mouse_LtT = "Características del enemigo",
  str_guide_mouse_Lb = "Ataca al Aurorian con la DEF más baja del equipo al atacar, causando daño. Intenta evitar desplegar Aurorianos con baja DEF en la batalla.",
  str_guide_mouse_LbT = "Estrategia de afrontamiento",
  str_guide_circle_2909301_Lt = "La leyenda cuenta que en la víspera del Festival de Primavera, un feroz demonio parecido a una bestia desciende sobre Longzhou, causando caos. Aquellos que logran expulsarlo son bendecidos con un año entero de paz y buena fortuna.",
  str_guide_circle_2909301_LtT = "Fiundling: Nian",
  str_guide_circle_2909301_Rt = "Lanza Habilidades Activas para asustar al Nian, ralentizando su avance.",
  str_guide_circle_2909301_RtT = "Estrategia de afrontamiento",
  str_guide_circle_2909301_Lb = "Salta hacia adelante e inflige daño, haciendo que 1 grupo circundante sea intransitable. Si Nian destruye la puerta, la batalla termina en derrota.",
  str_guide_circle_2909301_LbT = "Características del enemigo",
  str_guide_circle_80050001_Rt = "Obtiene 10 puntos de Energía de Combate al comienzo de cada ronda. Otorga un impulso de ATK a todos los monstruos en el campo si hay más de 30 puntos de energía al final de la ronda.",
  str_guide_circle_80050001_RtT = "Intel Eclipsite - Mensajero",
  str_guide_circle_80050001_Rb = "Cuando los Aurorianos infligen daño al Mensajero con Habilidades Activas y Ataques Normales, pueden disminuir su Energía de Combate. El Mensajero inflige daño a todos los monstruos en el campo al ser eliminado.",
  str_guide_circle_80050001_RbT = "Estrategia de afrontamiento",
  str_guide_warn_80050111 = "¡Navegante, mira aquí! ¡Has ganado una nueva habilidad en el Sueño!",
  str_guide_warn_80050112 = "Tus habilidades se fortalecerán a medida que te adentres más en los sueños. ¡Haz buen uso de ellas!",
  str_guide_circle_80150101 = "El equipo ya no se mueve de acuerdo con las reglas originales, sino que consume Puntos de Fuerza para el movimiento, independientemente del color de la casilla.",
  str_guide_circle_80150102 = "Aquí se muestran los Puntos de Fuerza del jugador, listados de izquierda a derecha como Puntos de Fuerza Actuales, Almacenamiento Máximo y Recuperación de Puntos de Fuerza.",
  str_guide_circle_80150103 = "Al comienzo de cada ronda, los jugadores restauran automáticamente los Puntos de Fuerza según la cantidad mostrada en la Recuperación de Puntos de Fuerza, que aumenta con cada ronda.",
  str_guide_circle_80150201 = "En este juego, los jugadores recuperan 1 Punto de Fuerza por cada Ficha Oscura consumida.",
  str_guide_circle_80150301 = "Toca para seleccionar una Roca y consume Puntos de Fuerza para eliminarla.",
  str_guide_circle_80250101 = "En este juego, cuando los jugadores desatan habilidades de Combo en Cadena, las Casillas Oscuras se consideran como 2 casillas para el consumo.",
  str_guide_circle_2921201_Lt = "El capitán de los Cazadores Silenciosos ahora ha dirigido su espada contra los mismos compañeros de equipo que siempre confían en él... Así es cuánto ha transigido con el reino.",
  str_guide_circle_2921201_LtT = "Claymore",
  str_guide_circle_2921201_Rt = "Basado en las condiciones del campo de batalla, Claymore puede elegir moverse conectando casillas y luego atacar, o lanzar un Doble Golpe después de un movimiento regular. A medida que disminuye su HP, puede desatar habilidades especiales para tallar el campo de batalla, luchando contra oponentes en un espacio más confinado.",
  str_guide_circle_2921201_RtT = "Características del enemigo",
  str_guide_circle_2921201_Lb = "Asegúrate de no ser golpeado por habilidades especiales; el resto depende de tus capacidades.",
  str_guide_circle_2921201_LbT = "Estrategia de afrontamiento",
  str_guide_circle_2909401_Lt = "Un enigmático y formidable Wraith, recorriendo las tierras para entrenar. Su aliento exuda terror, presagiando la perdición para aquellos que incurran en su ira.",
  str_guide_circle_2909401_LtT = "Ira",
  str_guide_circle_2909401_Rt = "Capaz de invocar Shadowfire con Darkflow en batalla.",
  str_guide_circle_2909401_RtT = "Características del enemigo",
  str_guide_circle_2909401_Lb = "Nota: El Meteorito Darkflow de Ira, compuesto por llamas furiosas, puede matar instantáneamente a los aurorianos dentro de su rango. ¡Presta atención a las áreas de advertencia y esquiva rápidamente!",
  str_guide_circle_2909401_LbT = "Estrategia de afrontamiento",
  str_guide_n43_1 = "¡Destellos de Luz ya están disponibles!\n¡Comencemos una nueva historia en el Segundo Interludio!",
  str_guide_n43_2 = "Los capítulos de la historia que se desbloquean en este evento, así como los capítulos que se han explorado hasta ahora, se muestran aquí.",
  str_guide_n43_3 = "Toca Explorar Ahora para ir directamente al mapa de exploración. Gasta Prisma en las etapas de la historia principal y de Incursión de Recursos para obtener Plumas de Caelestite.",
  str_guide_n43_4 = "En Aurora Exchange, usa las Plumas Caelestite para canjear varias recompensas.",
  str_guide_n43_5 = "¡Enfréntate a las etapas de la historia del evento y completa las misiones en tu Libro de eventos especiales!",
  str_guide_n43_6 = "Recuerda iniciar sesión en el juego todos los días para obtener las recompensas de Inicio de Sesión de Navegación.",
  str_guide_n43_7 = "Si tiene alguna pregunta sobre el evento, puede ver la descripción detallada aquí.",
  str_guide_warn_90010702 = "Aviso: Toca aquí para abrir la pantalla de la Esfera de Sueño.",
  str_guide_warn_90010703 = "Aviso: Hay múltiples ranuras en la Espiral de Iluminación. Coloca el Orbe de Sueño en una ranura vacía para analizarlo y liberar su poder.",
  str_guide_warn_90010704 = "Aviso: Toca el Orbe de Sueño para ver sus detalles.",
  str_guide_warn_90010705 = "Aviso: Toca el botón Equipar para colocar el Orbe de Sueño en la Espiral de Iluminación. También puedes arrastrar el Orbe de Sueño directamente a una ranura vacía.",
  str_guide_warn_90010706 = "Comentario: Se necesita suficiente energía para liberar el poder de los Orbes de Sueño en la Espiral de Iluminación. Pero no te preocupes; como tu Enlightener, creo que puedes acumular suficiente energía en la batalla.",
  str_guide_warn_90010707 = "Aviso: Si posees múltiples Orbes de Sueño, considera fusionarlos para adquirir Orbes de Sueño de nivel superior.",
  str_guide_warn_90010708 = "Dos Orbes de Sueño del mismo nivel pueden ser sintetizados en 1 Orbe de Sueño que es 1 nivel más alto.",
  str_guide_warn_90010709 = "Aviso: Si tienes alguna pregunta, puedes ver la descripción detallada aquí.",
  str_guide_circle_2004901_LbT = "Bruma",
  str_guide_circle_2004901_Lb = "Formado por la rápida acumulación de Darkflow alrededor de los enemigos muertos. ¡Ten cuidado! La ira y el resentimiento de tus enemigos perduran dentro de él.",
  str_guide_circle_2004901_RtT = "Características del enemigo",
  str_guide_circle_2004901_Rt = "Todo el daño que recibe se reduce a 1. No puede atacar, pero seguirá moviéndose hacia los Aurorianos.\nLa neblina no se cuenta para las condiciones de actualización de oleada y victoria de etapa.",
  str_guide_circle_2004901_RbT = "Estrategia de afrontamiento",
  str_guide_circle_2004901_Rb = "La neblina desaparece inmediatamente al ser empujada hacia atrás, arrastrada o forzada a moverse. Desaparece normalmente después de un cierto número de rondas.",
  str_guide_circle_80060313_LbT = "Afijo de élite: Neblina",
  str_guide_circle_80060313_Lb = "Los enemigos que tienen este sufijo de élite generarán Neblina al morir, con la cantidad generada determinada por el tamaño del enemigo.\nToca en el enemigo para ver más detalles.",
  str_guide_circle_2909501_LbT = "Zanahoria: Plaga",
  str_guide_circle_2909501_Lb = "Después de absorber demasiado resentimiento en un lugar oscuro y pudrirse, esta zanahoria se ha transformado en una criatura extraña que busca venganza después de obtener el poder de Darkflow.",
  str_guide_circle_2909501_RtT = "Características del enemigo",
  str_guide_circle_2909501_Rt = "Lanza zanahorias, causando múltiples instancias de daño. Cuando gira a alta velocidad, inflige múltiples instancias de daño a los enemigos en un área grande y los derriba.",
  str_guide_circle_2909501_RbT = "Estrategia de afrontamiento",
  str_guide_circle_2909501_Rb = "Este enemigo es bastante grande. ¡Despliega a los Aurorianos Detonadores para derrotarlo!",
  str_guide_circle_2909502_LbT = "Zanahoria: Plaga",
  str_guide_circle_2909502_Lb = "Después de absorber demasiado resentimiento en un lugar oscuro y pudrirse, esta zanahoria se ha transformado en una criatura extraña que busca venganza después de obtener el poder de Darkflow.",
  str_guide_circle_2909502_RtT = "Características del enemigo",
  str_guide_circle_2909502_Rt = "Lanza zanahorias, causando múltiples instancias de daño. Cuando gira a alta velocidad, inflige múltiples instancias de daño a los enemigos en un área grande y los derriba. En situaciones de emergencia, puede encogerse y enterrarse en el suelo para continuar luchando desde allí.",
  str_guide_circle_2909502_RbT = "Estrategia de afrontamiento",
  str_guide_circle_2909502_Rb = "Este enemigo es bastante grande. ¡Despliega a los Aurorianos Detonadores para derrotarlo!\nNota: ¡Este enemigo se transforma en su forma de 4 casillas cuando es invencible!",
  str_guide_circle_80060101_RtT = "Sangrado de Sueño",
  str_guide_circle_80060101_Rt = "Un aspecto único del Sueño actual que convierte todos los efectos de Sangrado en efectos de Herida. Cualquier cosa que desencadene efectos de Sangrado también desencadenará efectos de Herida.",
  str_guide_circle_80060101_RbT = "Mecánicos heridos",
  str_guide_circle_80060101_Rb = "Mientras están Heridos, los enemigos reciben daño cada ronda basado en el ATK promedio del equipo Auroriano. Cuanto mayor sea el porcentaje de HP del equipo Auroriano, más acumulaciones de Herido se pueden aplicar, y más daño se puede infligir. Herido se acumula hasta 5 veces, y no desaparece cuando la ronda termina.",
  str_guide_circle_80060102_LtT = "Estado de los Heridos",
  str_guide_circle_80060102_Lt = "Los enemigos en las primeras etapas comenzarán con 1 acumulación de Herido por defecto y recibirán daño de Herido en cada ronda. Toca a un enemigo para ver sus efectos de Herido.",
  str_guide_circle_80060201_RtT = "Piedrita Explosiva",
  str_guide_circle_80060201_Rt = "Una piedrita aparentemente ordinaria, pero altamente explosiva. Al ser destruida, inflige daño a todos los enemigos cercanos e inflige 1 pila de Heridas.",
  str_guide_circle_80060201_LtT = "Explosión expansiva",
  str_guide_circle_80060201_Lt = "Algunas piedritas son sorprendentemente duraderas y solo detonarán después de ser golpeadas varias veces, lo que aumenta su radio de explosión en 1 casilla por cada HP de Conteo que tengan.",
  str_guide_circle_80060401_RtT = "Espina Afilada Alterada",
  str_guide_circle_80060401_Rt = "Un Spikepest de apariencia familiar que ya no representa una amenaza para los Aurorianos. Al final de cada ronda, daña e inflige 1 pila de Heridas a todos los enemigos atrapados en sus picos.",
  str_guide_circle_2909701_LbT = "Magmita insaciable",
  str_guide_circle_2909701_Lb = "Un tipo aberrante de Eclipsite que utiliza tanto la lava como el Darkflow para causar daño.",
  str_guide_circle_2909701_RtT = "Características del enemigo",
  str_guide_circle_2909701_Rt = "Puede infligir daño en un área grande, así como invocar un escudo de magma para protegerse.",
  str_guide_circle_2909701_RbT = "Estrategia de afrontamiento",
  str_guide_circle_2909701_Rb = "Mientras está protegido por su escudo de magma, Insatiable Magmite refleja todos los ataques normales entrantes. ¡Asegúrate de estar atento a las erupciones de Fuego de Tierra desde el suelo!",
  str_guide_warn_811400101 = "Durante el evento de Presagios Mortales, puedes desafiar a diferentes Presagios que se desbloquearán gradualmente con el tiempo.",
  str_guide_warn_811400102 = "Toca un Presagio para ir a la interfaz del desafío.",
  str_guide_warn_811400103 = "Cada Presagio tiene tres niveles de dificultad. Aquí, puedes elegir libremente entre ellos.",
  str_guide_warn_811400104 = "Aquí es donde puedes ver las condiciones del campo de batalla y aprender más sobre los atributos del jefe del Presagio.",
  str_guide_warn_811400105 = "En cada presagio, puedes elegir de uno a tres efectos de mejora para hacerte más fuerte. Cuanto mayor sea la dificultad, más efectos de mejora puedes seleccionar.",
  str_guide_warn_811400106 = "Toque en una ranura para seleccionar un efecto de mejora.",
  str_guide_warn_811400107 = "Cada efecto de mejora se divide en 3 áreas, y cada área debe desbloquearse en orden de arriba a abajo.",
  str_guide_warn_811400108 = "Toca en una caja para seleccionar el efecto de mejora correspondiente.",
  str_guide_warn_811400109 = "Toca para confirmar y guardar los efectos de mejora seleccionados.",
  str_guide_warn_811400110 = "Despeja las etapas para completar las misiones de desafío y reclamar grandes recompensas.",
  str_guide_circle_2909801_LbT = "Punta de lanza: Aguijón de Rotbone",
  str_guide_circle_2909801_Lb = "Una vez un Coloso de batalla que se lanzó de cabeza a la refriega en nombre del Eclipse, ahora es solo un montón de escombros destrozados, su última amenaza restante yace en su coxis.",
  str_guide_circle_2909801_RtT = "Características del enemigo",
  str_guide_circle_2909801_Rt = "Capaz de infligir daño a objetivos en un área grande y generar unidades periféricas que se mueven en formación de grupo para bloquear a los aurorianos.",
  str_guide_circle_2909801_RbT = "Estrategia de afrontamiento",
  str_guide_circle_2909801_Rb = "Convoca constantemente unidades periféricas para defenderse. Evítalas para infligirles daño.",
  str_guide_2005101_Rt = "Originalmente una parte de la cola de Spearhead, estas piezas se rompieron una por una y se esparcieron por las ruinas subterráneas.",
  str_guide_2005101_RtT = "Provocante Periferia",
  str_guide_2005101_Lt = "Monstruos voladores controlados por una fuerza misteriosa, constantemente forman formaciones extrañas para lanzar ataques a corta distancia a los intrusos.",
  str_guide_2005101_LtT = "Características del enemigo",
  str_guide_2005101_Lb = "Las unidades periféricas pueden rodear rápidamente a sus objetivos. Destrúyelos en sus articulaciones lo antes posible para prevenir esto.",
  str_guide_2005101_LbT = "Estrategia de afrontamiento",
  str_guide_2910001_Lt = "Puede atacar a los Aurorianos con varias partes del cuerpo. Dañar cualquier parte de Syurton le hará daño.",
  str_guide_2910001_LtT = "Características del enemigo",
  str_guide_2910001_Lb = "¡Esquiva los ataques e intenta golpear varias partes a la vez!",
  str_guide_2910001_LbT = "Estrategia de afrontamiento",
  str_guide_2910002_Lt = "Puede atacar a los Aurorianos con varias partes del cuerpo. Dañar cualquier parte de Syurton le hará daño.",
  str_guide_2910002_LtT = "Características del enemigo",
  str_guide_2910002_Lb = "¡Cuidado! ¡La cola de Syurton solo recibe daño de un solo objetivo!",
  str_guide_2910002_LbT = "Estrategia de afrontamiento",
  str_guide_circle_2910101_Lb = "Jefe de la familia Porfirio. Es alguien a quien le gusta dominar a los demás y persigue incansablemente el poder por cualquier medio.",
  str_guide_circle_2910101_LbT = "David Porfirio",
  str_guide_circle_2910101_Rt = "Cuando la cordura es 50 o más, convoca a los secuaces Necroservant. Cuando está por debajo de 50, ataca a los Aurorianos para restaurar su propio HP y convocar a los Necroservants.",
  str_guide_circle_2910101_RtT = "Características del enemigo",
  str_guide_circle_2910101_Rb = "Gestiona la cordura y responde a las amenazas de David Porfirio según la situación.",
  str_guide_circle_2910101_RbT = "Estrategia de afrontamiento",
  str_guide_circle_2005201_Lb = "Almas partidas miserables, eternamente engañadas y confinadas. Ahora vagan, buscando sangre fresca y cálida para su maestro.",
  str_guide_circle_2005201_LbT = "Sirviente Necro",
